294	    WebSocketSendInfo WebSocketTransport::sendHeartBeat(SendMessageKind pingMessage)
295	    {
296	        _pongReceived = false;
297	        std::stringstream ss;
298	
299	        ss << _kPingMessage;
300	        if (!_setCustomMessage)
301	        {
302	            ss << "::" << _pingIntervalSecs << "s"
303	               << "::" << _pingCount++;
304	        }
305	        if (pingMessage == SendMessageKind::Ping)
306	        {
307	            return sendPing(ss.str());
308	        }
309	        else if (pingMessage == SendMessageKind::Binary)
310	        {
311	            WebSocketSendInfo info = sendBinary(ss.str(), nullptr);
312	            if (info.success)
313	            {
314	                std::lock_guard<std::mutex> lck(_lastSendPingTimePointMutex);
315	                _lastSendPingTimePoint = std::chrono::steady_clock::now();
316	            }
317	            return info;
318	        }
319	        else if (pingMessage == SendMessageKind::Text)
320	        {
321	            WebSocketSendInfo info = sendText(ss.str(), nullptr);
322	            if (info.success)
323	            {
324	                std::lock_guard<std::mutex> lck(_lastSendPingTimePointMutex);
325	                _lastSendPingTimePoint = std::chrono::steady_clock::now();
326	            }
327	            return info;
328	        }
329	
330	        // unknow type ping message
331	        return {};
332	    }
