881	
882	    WebSocketSendInfo WebSocketTransport::sendData(wsheader_type::opcode_type type,
883	                                                   const IXWebSocketSendData& message,
884	                                                   bool compress,
885	                                                   const OnProgressCallback& onProgressCallback)
886	    {
887	        if (_readyState != ReadyState::OPEN && _readyState != ReadyState::CLOSING)
888	        {
889	            return WebSocketSendInfo(false);
890	        }
891	
892	        size_t payloadSize = message.size();
893	        size_t wireSize = message.size();
894	        bool compressionError = false;
895	
896	        auto message_begin = message.cbegin();
897	        auto message_end = message.cend();
898	
899	        if (compress)
900	        {
901	            if (!_perMessageDeflate->compress(message, _compressedMessage))
902	            {
903	                bool success = false;
904	                compressionError = true;
905	                payloadSize = 0;
906	                wireSize = 0;
907	                return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
908	            }
909	            compressionError = false;
910	            wireSize = _compressedMessage.size();
911	
912	            IXWebSocketSendData compressedSendData(_compressedMessage);
913	            message_begin = compressedSendData.cbegin();
914	            message_end = compressedSendData.cend();
915	        }
916	
917	        {
918	            std::lock_guard<std::mutex> lock(_txbufMutex);
919	            _txbuf.reserve(wireSize);
920	        }
921	
922	        bool success = true;
923	
924	        // Common case for most message. No fragmentation required.
925	        if (wireSize < kChunkSize)
926	        {
927	            success = sendFragment(type, true, message_begin, message_end, compress);
928	
929	            if (onProgressCallback)
930	            {
931	                onProgressCallback(0, 1);
932	            }
933	        }
934	        else
935	        {
936	            //
937	            // Large messages need to be fragmented
938	            //
939	            // Rules:
940	            // First message needs to specify a proper type (BINARY or TEXT)
941	            // Intermediary and last messages need to be of type CONTINUATION
942	            // Last message must set the fin byte.
943	            //
944	            auto steps = wireSize / kChunkSize;
945	
946	            auto begin = message_begin;
947	            auto end = message_end;
948	
949	            for (uint64_t i = 0; i < steps; ++i)
950	            {
951	                bool firstStep = i == 0;
952	                bool lastStep = (i + 1) == steps;
953	                bool fin = lastStep;
954	
955	                end = begin + kChunkSize;
956	                if (lastStep)
957	                {
958	                    end = message_end;
959	                }
960	
961	                auto opcodeType = type;
962	                if (!firstStep)
963	                {
964	                    opcodeType = wsheader_type::CONTINUATION;
965	                }
966	
967	                // Send message
968	                if (!sendFragment(opcodeType, fin, begin, end, compress))
969	                {
970	                    return WebSocketSendInfo(false);
971	                }
972	
973	                if (onProgressCallback && !onProgressCallback((int) i, (int) steps))
974	                {
975	                    break;
976	                }
977	
978	                begin += kChunkSize;
979	            }
980	        }
981	
982	        // Request to flush the send buffer on the background thread if it isn't empty
983	        if (!isSendBufferEmpty())
984	        {
985	            wakeUpFromPoll(SelectInterrupt::kSendRequest);
986	
987	            // FIXME: we should have a timeout when sending large messages: see #131
988	            if (_blockingSend && !flushSendBuffer())
989	            {
990	                success = false;
991	            }
992	        }
993	
994	        return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
995	    }
996	
997	    template<class Iterator>
998	    bool WebSocketTransport::sendFragment(wsheader_type::opcode_type type,
999	                                          bool fin,
1000	                                          Iterator message_begin,
1001	                                          Iterator message_end,
1002	                                          bool compress)
1003	    {
1004	        uint64_t message_size = static_cast<uint64_t>(message_end - message_begin);
1005	
1006	        unsigned x = getRandomUnsigned();
1007	        uint8_t masking_key[4] = {};
1008	        masking_key[0] = (x >> 24);
1009	        masking_key[1] = (x >> 16) & 0xff;
1010	        masking_key[2] = (x >> 8) & 0xff;
1011	        masking_key[3] = (x) &0xff;
1012	
1013	        std::vector<uint8_t> header;
1014	        header.assign(2 + (message_size >= 126 ? 2 : 0) + (message_size >= 65536 ? 6 : 0) +
1015	                          (_useMask ? 4 : 0),
1016	                      0);
1017	        header[0] = type;
1018	
1019	        // The fin bit indicate that this is the last fragment. Fin is French for end.
1020	        if (fin)
1021	        {
1022	            header[0] |= 0x80;
1023	        }
1024	
1025	        // The rsv1 bit indicate that the frame is compressed
1026	        // continuation opcodes should not set it. Autobahn 12.2.10 and others 12.X
1027	        if (compress && type != wsheader_type::CONTINUATION)
1028	        {
1029	            header[0] |= 0x40;
1030	        }
1031	
1032	        if (message_size < 126)
1033	        {
1034	            header[1] = (message_size & 0xff) | (_useMask ? 0x80 : 0);
1035	
1036	            if (_useMask)
1037	            {
1038	                header[2] = masking_key[0];
1039	                header[3] = masking_key[1];
1040	                header[4] = masking_key[2];
1041	                header[5] = masking_key[3];
1042	            }
1043	        }
1044	        else if (message_size < 65536)
1045	        {
1046	            header[1] = 126 | (_useMask ? 0x80 : 0);
1047	            header[2] = (message_size >> 8) & 0xff;
1048	            header[3] = (message_size >> 0) & 0xff;
1049	
1050	            if (_useMask)
1051	            {
1052	                header[4] = masking_key[0];
1053	                header[5] = masking_key[1];
1054	                header[6] = masking_key[2];
1055	                header[7] = masking_key[3];
1056	            }
1057	        }
1058	        else
1059	        { // TODO: run coverage testing here
1060	            header[1] = 127 | (_useMask ? 0x80 : 0);
1061	            header[2] = (message_size >> 56) & 0xff;
1062	            header[3] = (message_size >> 48) & 0xff;
1063	            header[4] = (message_size >> 40) & 0xff;
1064	            header[5] = (message_size >> 32) & 0xff;
1065	            header[6] = (message_size >> 24) & 0xff;
1066	            header[7] = (message_size >> 16) & 0xff;
1067	            header[8] = (message_size >> 8) & 0xff;
1068	            header[9] = (message_size >> 0) & 0xff;
1069	
1070	            if (_useMask)
1071	            {
1072	                header[10] = masking_key[0];
1073	                header[11] = masking_key[1];
1074	                header[12] = masking_key[2];
1075	                header[13] = masking_key[3];
1076	            }
1077	        }
1078	
1079	        // _txbuf will keep growing until it can be transmitted over the socket:
1080	        appendToSendBuffer(header, message_begin, message_end, message_size, masking_key);
1081	
1082	        // Now actually send this data
1083	        return sendOnSocket();
1084	    }
