1240	
1241	    void WebSocketTransport::close(uint16_t code,
1242	                                   const std::string& reason,
1243	                                   size_t closeWireSize,
1244	                                   bool remote)
1245	    {
1246	        _requestInitCancellation = true;
1247	
1248	        if (_readyState == ReadyState::CLOSING || _readyState == ReadyState::CLOSED)
1249	        {
1250	            // Wake up the socket polling thread, as
1251	            // Socket::isReadyToRead() might be still waiting the
1252	            // interrupt event to happen.
1253	            bool wakeUpPoll = false;
1254	            {
1255	              std::lock_guard<std::mutex> lock(_socketMutex);
1256	              wakeUpPoll = (_socket && _socket->isWakeUpFromPollSupported());
1257	            }
1258	            if (wakeUpPoll)
1259	            {
1260	                wakeUpFromPoll(SelectInterrupt::kCloseRequest);
1261	            }
1262	            return;
1263	        }
1264	
1265	        if (closeWireSize == 0)
1266	        {
1267	            closeWireSize = reason.size();
1268	        }
1269	
1270	        setCloseReason(reason);
1271	        _closeCode = code;
1272	        _closeWireSize = closeWireSize;
1273	        _closeRemote = remote;
1274	
1275	        {
1276	            std::lock_guard<std::mutex> lock(_closingTimePointMutex);
1277	            _closingTimePoint = std::chrono::steady_clock::now();
1278	        }
1279	        setReadyState(ReadyState::CLOSING);
1280	
1281	        sendCloseFrame(code, reason);
1282	
1283	        // wake up the poll, but do not close yet
1284	        wakeUpFromPoll(SelectInterrupt::kSendRequest);
1285	    }
