1292	
1293	    bool WebSocketTransport::flushSendBuffer()
1294	    {
1295	        auto start = std::chrono::steady_clock::now();
1296	
1297	        // timeoutMs tracks how long to wait before forcefully
1298	        // closing the socket when sending runs into a timeout.
1299	        std::chrono::seconds timeoutSecs(0);
1300	        if (_sendTimeoutSecs > 0)
1301	        {
1302	            timeoutSecs = std::chrono::seconds(_sendTimeoutSecs);
1303	        }
1304	        else if (_pingIntervalSecs > 0)
1305	        {
1306	            // If a pingInterval is set, use it as a timeout because if we cannot
1307	            // send out any data for pingInterval seconds, we may as well disconnet
1308	            // the client.
1309	            timeoutSecs = std::chrono::seconds(_pingIntervalSecs);
1310	        }
1311	
1312	        while (!isSendBufferEmpty() && !_requestInitCancellation)
1313	        {
1314	            // Wait with a 10ms timeout until the socket is ready to write.
1315	            // This way we are not busy looping
1316	            PollResultType result = _socket->isReadyToWrite(10);
1317	
1318	            if (result == PollResultType::Error)
1319	            {
1320	                closeSocket();
1321	                setReadyState(ReadyState::CLOSED);
1322	                return false;
1323	            }
1324	            else if (result == PollResultType::ReadyForWrite)
1325	            {
1326	                if (!sendOnSocket())
1327	                {
1328	                    return false;
1329	                }
1330	            }
1331	            else if (result == PollResultType::Timeout && timeoutSecs.count() > 0)
1332	            {
1333	                auto now = std::chrono::steady_clock::now();
1334	                // Timeout error and exceeded the allocated timeout: Treat
1335	                // as abnormal close and use "Send Timeout" for the reason.
1336	                if (now > start + timeoutSecs)
1337	                {
1338	                    closeSocketAndSwitchToClosedState(WebSocketCloseConstants::kAbnormalCloseCode,
1339	                                                      WebSocketCloseConstants::kSendTimeoutMessage,
1340	                                                      0,
1341	                                                      false);
1342	                    return false;
1343	                }
1344	            }
1345	        }
1346	
1347	        return true;
1348	    }
