66	            AbnormalClose,
67	            CannotFlushSendBuffer
68	        };
69	
70	        using OnMessageCallback =
71	            std::function<void(const std::string&, size_t, bool, MessageKind)>;
72	        using OnCloseCallback = std::function<void(uint16_t, const std::string&, size_t, bool)>;
73	
74	        WebSocketTransport();
75	        ~WebSocketTransport();
