87	        // Server
88	        WebSocketInitResult connectToSocket(std::unique_ptr<Socket> socket,
89	                                            int timeoutSecs,
90	                                            bool enablePerMessageDeflate,
91	                                            HttpRequestPtr request = nullptr,
92	                                            int sendTimeoutSecs = -1);
93	
94	        PollResult poll();
95	        WebSocketSendInfo sendBinary(const IXWebSocketSendData& message,
96	                                     const OnProgressCallback& onProgressCallback);
97	        WebSocketSendInfo sendText(const IXWebSocketSendData& message,
98	                                   const OnProgressCallback& onProgressCallback);
99	        WebSocketSendInfo sendPing(const IXWebSocketSendData& message);
100	
101	        void close(uint16_t code = WebSocketCloseConstants::kNormalClosureCode,
102	                   const std::string& reason = WebSocketCloseConstants::kNormalClosureMessage,
103	                   size_t closeWireSize = 0,
104	                   bool remote = false);
105	
106	        void closeSocket();
107	
108	        ReadyState getReadyState() const;
109	        void setReadyState(ReadyState readyState);
110	        void setOnCloseCallback(const OnCloseCallback& onCloseCallback);
111	        void dispatch(PollResult pollResult, const OnMessageCallback& onMessageCallback);
112	        size_t bufferedAmount() const;
113	
114	        // set ping heartbeat message
115	        void setPingMessage(const std::string& message, SendMessageKind pingType);
116	
117	        // internal
118	        // send any type of ping packet, not only 'ping' type
119	        WebSocketSendInfo sendHeartBeat(SendMessageKind pingType);
120	
121	    private:
122	        std::string _url;
123	
124	        struct wsheader_type
125	        {
126	            unsigned header_size;
127	            bool fin;
128	            bool rsv1;
129	            bool rsv2;
130	            bool rsv3;
131	            bool mask;
132	            enum opcode_type
133	            {
134	                CONTINUATION = 0x0,
135	                TEXT_FRAME = 0x1,
136	                BINARY_FRAME = 0x2,
137	                CLOSE = 8,
138	                PING = 9,
139	                PONG = 0xa,
140	            } opcode;
141	            int N0;
142	            uint64_t N;
143	            uint8_t masking_key[4];
144	        };
145	
146	        // Tells whether we should mask the data we send.
147	        // client should mask but server should not
148	        std::atomic<bool> _useMask;
149	
150	        // Tells whether we should flush the send buffer before
151	        // saying that a send is complete. This is the mode for server code.
152	        std::atomic<bool> _blockingSend;
153	
154	        // A configurable timeout for how long flushSendBuffer() may block
155	        // before forcefully closing the client socket with a "Send timeout"
156	        // message. This is useful when a client doesn't read from its socket
157	        // and the server stalls on trying to send more data.
158	        int _sendTimeoutSecs = -1;
159	
160	        // Buffer for reading from our socket. That buffer is never resized.
161	        std::vector<uint8_t> _readbuf;
162	
163	        // Contains all messages that were fetched in the last socket read.
164	        // This could be a mix of control messages (Close, Ping, etc...) and
165	        // data messages. That buffer is resized
166	        std::vector<uint8_t> _rxbuf;
167	
168	        // If set to a positive value, only read bytes from the socket until
169	        // _rxbuf has reached this size to avoid unnecessary erase churn.
170	        uint64_t _rxbufWanted = 0;
171	
172	        // Contains all messages that are waiting to be sent
173	        std::vector<uint8_t> _txbuf;
174	        mutable std::mutex _txbufMutex;
175	
176	        // Hold fragments for multi-fragments messages in a list. We support receiving very large
177	        // messages (tested messages up to 700M) and we cannot put them in a single
178	        // buffer that is resized, as this operation can be slow when a buffer has its
179	        // size increased 2 fold, while appending to a list has a fixed cost.
180	        std::list<std::string> _chunks;
181	
182	        // Record the message kind (will be TEXT or BINARY) for a fragmented
183	        // message, present in the first chunk, since the final chunk will be a
184	        // CONTINUATION opcode and doesn't tell the full message kind
185	        MessageKind _fragmentedMessageKind;
186	
187	        // Ditto for whether a message is compressed
188	        bool _receivedMessageCompressed;
189	
190	        // Set when a protocol error was detected while receiving frames.
191	        // From then on incoming frames (except CLOSE ones, which are still
192	        // processed to complete the closing handshake) are dropped while
193	        // the connection is closing.
194	        bool _protocolError;
195	
196	        // Fragments are 32K long
197	        static constexpr size_t kChunkSize = 1 << 15;
198	
199	        // Underlying TCP socket
200	        std::unique_ptr<Socket> _socket;
201	        std::mutex _socketMutex;
202	
203	        // Hold the state of the connection (OPEN, CLOSED, etc...)
204	        std::atomic<ReadyState> _readyState;
205	        // Mutex to serialize setReadyState() execution.
206	        std::mutex _setReadyStateMutex;
207	
208	        OnCloseCallback _onCloseCallback;
209	        std::string _closeReason;
210	        mutable std::mutex _closeReasonMutex;
211	        std::atomic<uint16_t> _closeCode;
212	        std::atomic<size_t> _closeWireSize;
213	        std::atomic<bool> _closeRemote;
214	
215	        // Data used for Per Message Deflate compression (with zlib)
216	        WebSocketPerMessageDeflatePtr _perMessageDeflate;
217	        WebSocketPerMessageDeflateOptions _perMessageDeflateOptions;
218	        std::atomic<bool> _enablePerMessageDeflate;
219	
220	        std::string _decompressedMessage;
221	        std::string _compressedMessage;
