187	    void WebSocket::stop(uint16_t code, const std::string& reason)
188	    {
189	        const bool isJoinable = _thread.joinable();
190	
191	        if(isJoinable)
192	        {
193	            // we need to set _stop before close()
194	            // otherwise automatic reconnection might restart the connection before _stop has a chance to get set
195	            // this can happen during high CPU load => _thread.join() below blocks indefinitely
196	            _stop = true;
197	            _sleepCondition.notify_one();
198	        }
199	
200	        close(code, reason);
201	
202	        if (isJoinable)
203	        {
204	            // wait until working thread will exit
205	            // it will exit after close operation is finished
206	            _thread.join();
207	            _stop = false;
208	        }
