114	        while (out.find("\r\n\r\n") == std::string::npos)
115	        {
116	            ssize_t ret = recv(fd, &c, 1, 0);
117	            if (ret <= 0) return false;
118	            out.push_back(c);
119	            if (out.size() > 1 << 16) return false;
120	        }
121	        return true;
122	    }
123	
124	    std::string extractHeader(const std::string& request, const std::string& name)
125	    {
126	        std::string lower;
127	        lower.resize(request.size());
128	        for (size_t i = 0; i < request.size(); ++i)
129	        {
130	            lower[i] = (char) tolower(request[i]);
131	        }
132	
133	        std::string key = name + ":";
134	        auto pos = lower.find(key);
135	        if (pos == std::string::npos) return "";
136	
137	        pos += key.size();
138	        while (pos < request.size() && request[pos] == ' ')
139	            pos++;
140	
141	        auto end = request.find("\r\n", pos);
142	        return request.substr(pos, end - pos);
143	    }
144	
145	    //
146	    // WebSocket frame helpers
147	    //
148	    struct Frame
149	    {
150	        bool fin = false;
151	        bool rsv1 = false;
152	        uint8_t opcode = 0;
153	        std::string payload;
154	    };
155	
156	    std::string encodeFrame(uint8_t opcode,
157	                            bool fin,
158	                            bool rsv1,
159	                            const std::string& payload,
160	                            bool masked)
161	    {
162	        std::string out;
163	
164	        uint8_t b0 = opcode & 0x0f;
165	        if (fin) b0 |= 0x80;
166	        if (rsv1) b0 |= 0x40;
167	        out.push_back((char) b0);
168	
169	        uint8_t maskBit = masked ? 0x80 : 0;
170	        size_t n = payload.size();
171	        if (n < 126)
172	        {
173	            out.push_back((char) (maskBit | n));
174	        }
175	        else if (n < 65536)
176	        {
177	            out.push_back((char) (maskBit | 126));
178	            out.push_back((char) ((n >> 8) & 0xff));
179	            out.push_back((char) (n & 0xff));
180	        }
181	        else
182	        {
183	            out.push_back((char) (maskBit | 127));
184	            for (int i = 7; i >= 0; --i)
185	            {
186	                out.push_back((char) ((n >> (8 * i)) & 0xff));
187	            }
188	        }
189	
190	        uint8_t key[4] = {0x12, 0x34, 0x56, 0x78};
191	        if (masked)
192	        {
193	            out.append((char*) key, 4);
194	        }
195	
196	        for (size_t i = 0; i < n; ++i)
197	        {
198	            char c = payload[i];
199	            if (masked) c ^= key[i & 3];
200	            out.push_back(c);
201	        }
202	
203	        return out;
204	    }
205	
206	    bool readFrame(int fd, Frame& f)
207	    {
208	        char hdr[2];
209	        if (!readExact(fd, hdr, 2)) return false;
210	
211	        f.fin = (hdr[0] & 0x80) != 0;
212	        f.rsv1 = (hdr[0] & 0x40) != 0;
213	        f.opcode = (uint8_t)(hdr[0] & 0x0f);
214	
215	        bool masked = (hdr[1] & 0x80) != 0;
216	        uint64_t n = (uint64_t)(hdr[1] & 0x7f);
217	        if (n == 126)
218	        {
219	            char e[2];
220	            if (!readExact(fd, e, 2)) return false;
221	            n = ((uint64_t)(uint8_t) e[0] << 8) | (uint8_t) e[1];
222	        }
223	        else if (n == 127)
224	        {
225	            char e[8];
226	            if (!readExact(fd, e, 8)) return false;
227	            n = 0;
228	            for (int i = 0; i < 8; ++i)
229	            {
230	                n = (n << 8) | (uint8_t) e[i];
231	            }
232	        }
233	
234	        uint8_t key[4] = {};
235	        if (masked && !readExact(fd, (char*) key, 4)) return false;
236	
237	        f.payload.assign((size_t) n, 0);
238	        if (n > 0 && !readExact(fd, &f.payload[0], (size_t) n)) return false;
239	
240	        if (masked)
241	        {
242	            for (uint64_t i = 0; i < n; ++i)
243	            {
244	                f.payload[i] ^= key[i & 3];
245	            }
246	        }
247	
248	        return true;
249	    }
250	
251	    bool waitFor(const std::function<bool()>& pred, int timeoutMs)
252	    {
253	        int waited = 0;
254	        while (waited < timeoutMs)
255	        {
256	            if (pred()) return true;
257	            ix::msleep(10);
258	            waited += 10;
259	        }
260	        return pred();
261	    }
262	
263	    std::string makeBigPayload()
264	    {
265	        // Pseudo random (hardly compressible) payload, larger than the 32KiB
266	        // internal read chunk size, so that the frame is read in several goes.
267	        std::string out;
268	        out.resize(40000);
269	        uint32_t x = 12345;
270	        for (size_t i = 0; i < out.size(); ++i)
271	        {
272	            x = x * 1103515245 + 12345;
273	            out[i] = (char) (x >> 16);
274	        }
275	        return out;
276	    }
