278	    //
279	    // What the raw peer observes back from the ix endpoint
280	    //
281	    struct PeerObservation
282	    {
283	        std::vector<size_t> validCompressedSizes; // compressed size of each valid message sent
284	        size_t invalidPayloadSize = 0;
285	        int pongCount = 0;
286	        int unexpectedFrameCount = 0;
287	        bool gotClose = false;
288	        uint16_t closeCode = 0;
289	        std::string closeReason;
290	        std::string harnessError;
291	    };
292	
293	    //
294	    // Events recorded on the ix side under test
295	    //
296	    struct RecordedEvents
297	    {
298	        std::mutex mutex;
299	        int openCount = 0;
300	        std::vector<std::string> messages;
301	        std::vector<bool> messageBinary;
302	        std::vector<size_t> messageWireSizes;
303	        int fragmentCount = 0;
304	        int pingCount = 0;
305	        int pongCount = 0;
306	        int errorCount = 0;
307	        bool errorDecompression = false;
308	        bool errorStrEmpty = false;
309	        std::string errorReason;
310	        size_t errorWireSize = 0;
311	        ix::ReadyState readyStateAtError = ix::ReadyState::Open;
312	        bool sendSucceededAtError = true;
313	        int closeCount = 0;
314	        uint16_t closeCode = 0;
315	        std::string closeReason;
316	        bool closeRemote = true;
317	    };
318	
319	    void recordEvent(ix::WebSocket& ws, RecordedEvents& ev, const ix::WebSocketMessagePtr& msg)
320	    {
321	        if (msg->type == ix::WebSocketMessageType::Error)
322	        {
323	            // The connection must already be closing, and sending must fail.
324	            ix::ReadyState state = ws.getReadyState();
325	            bool sendOk = ws.sendText("should fail").success;
326	
327	            std::lock_guard<std::mutex> lock(ev.mutex);
328	            ev.errorCount++;
329	            ev.errorDecompression = msg->errorInfo.decompressionError;
330	            ev.errorStrEmpty = msg->str.empty();
331	            ev.errorReason = msg->errorInfo.reason;
332	            ev.errorWireSize = msg->wireSize;
333	            ev.readyStateAtError = state;
334	            ev.sendSucceededAtError = sendOk;
335	            return;
336	        }
337	
338	        std::lock_guard<std::mutex> lock(ev.mutex);
339	        switch (msg->type)
340	        {
341	            case ix::WebSocketMessageType::Open: ev.openCount++; break;
342	            case ix::WebSocketMessageType::Message:
343	                ev.messages.push_back(msg->str);
344	                ev.messageBinary.push_back(msg->binary);
345	                ev.messageWireSizes.push_back(msg->wireSize);
346	                break;
347	            case ix::WebSocketMessageType::Fragment: ev.fragmentCount++; break;
348	            case ix::WebSocketMessageType::Ping: ev.pingCount++; break;
349	            case ix::WebSocketMessageType::Pong: ev.pongCount++; break;
350	            case ix::WebSocketMessageType::Close:
351	                ev.closeCount++;
352	                ev.closeCode = msg->closeInfo.code;
353	                ev.closeReason = msg->closeInfo.reason;
354	                ev.closeRemote = msg->closeInfo.remote;
355	                break;
356	            default: break;
357	        }
358	    }
359	
360	    struct ClientScenarioOptions
361	    {
362	        uint8_t invalidOpcode = 0x1; // text
363	        std::string invalidPayload = std::string("\x07", 1);
364	        bool fragmentInvalid = false; // split the invalid payload in 2 frames, ping in between
365	        int delayAfterInvalidMs = 0;  // delay before sending trailing valid traffic
366	        bool echoClose = true;        // whether to answer the CLOSE frame back
367	    };
368	
369	    //
370	    // A raw WebSocket server which sends valid compressed messages, then an
371	    // invalid compressed message, then more (valid) traffic which must be
372	    // dropped by the client. It then expects a CLOSE frame with code 1007.
373	    //
374	    void rawServerMain(int listenFd,
375	                       ClientScenarioOptions opts,
376	                       std::string bigPayload,
377	                       std::shared_ptr<PeerObservation> obs)
378	    {
379	        int fd = accept(listenFd, nullptr, nullptr);
380	        if (fd < 0)
381	        {
382	            obs->harnessError = "accept failed";
383	            return;
384	        }
385	        setRecvTimeout(fd, 15);
386	
387	        std::string request;
388	        if (!readHttpHeaders(fd, request))
389	        {
390	            obs->harnessError = "reading http request failed";
391	            close(fd);
392	            return;
393	        }
394	
395	        std::string key = extractHeader(request, "sec-websocket-key");
396	        char output[29] = {};
397	        WebSocketHandshakeKeyGen::generate(key, output);
398	
399	        std::string response = "HTTP/1.1 101 Switching Protocols\r\n"
400	                               "Upgrade: websocket\r\n"
401	                               "Connection: Upgrade\r\n"
402	                               "Sec-WebSocket-Accept: " +
403	                               std::string(output) +
404	                               "\r\n"
405	                               "Sec-WebSocket-Extensions: permessage-deflate\r\n"
406	                               "\r\n";
407	        if (!sendAll(fd, response))
408	        {
409	            obs->harnessError = "sending handshake response failed";
410	            close(fd);
411	            return;
412	        }
413	
414	        // Keep the compression context between messages (context takeover)
415	        WebSocketPerMessageDeflateCompressor compressor;
416	        compressor.init(15, false);
417	
418	        auto sendValid = [&](uint8_t opcode, const std::string& data) {
419	            std::string compressed;
420	            compressor.compress(data, compressed);
421	            obs->validCompressedSizes.push_back(compressed.size());
422	            sendAll(fd, encodeFrame(opcode, true, true, compressed, false));
423	        };
424	
425	        // A few valid compressed messages: text, empty, large binary,
426	        // repeated text (context takeover) ...
427	        sendValid(0x1, "hello");
428	        sendValid(0x1, "");
429	        sendValid(0x2, bigPayload);
430	        sendValid(0x1, "hello");
431	
432	        // ... and a fragmented one, with a ping interleaved between fragments
433	        {
434	            std::string compressed;
435	            compressor.compress(std::string("fragmented valid payload"), compressed);
436	            obs->validCompressedSizes.push_back(compressed.size());
437	
438	            size_t cut = 3;
439	            sendAll(fd, encodeFrame(0x1, false, true, compressed.substr(0, cut), false));
440	            sendAll(fd, encodeFrame(0x9, true, false, "p1", false));
441	            sendAll(fd, encodeFrame(0x0, true, false, compressed.substr(cut), false));
442	        }
443	
444	        // The invalid message
445	        obs->invalidPayloadSize = opts.invalidPayload.size();
446	        if (opts.fragmentInvalid)
447	        {
448	            size_t cut = opts.invalidPayload.size() / 2;
449	            sendAll(fd, encodeFrame(opts.invalidOpcode, false, true,
450	                                    opts.invalidPayload.substr(0, cut), false));
451	            sendAll(fd, encodeFrame(0x9, true, false, "p2", false));
452	            sendAll(fd, encodeFrame(0x0, true, false, opts.invalidPayload.substr(cut), false));
453	        }
454	        else
455	        {
456	            sendAll(fd, encodeFrame(opts.invalidOpcode, true, true, opts.invalidPayload, false));
457	        }
458	
459	        if (opts.delayAfterInvalidMs > 0)
460	        {
461	            ix::msleep(opts.delayAfterInvalidMs);
462	        }
463	
464	        // Trailing traffic, must be dropped (no message, no pong reply)
465	        {
466	            std::string compressed;
467	            compressor.compress(std::string("world"), compressed);
468	            sendAll(fd, encodeFrame(0x1, true, true, compressed, false));
469	            sendAll(fd, encodeFrame(0x9, true, false, "p3", false));
470	        }
471	
472	        // Read frames until the CLOSE one
473	        Frame f;
474	        while (readFrame(fd, f))
475	        {
476	            if (f.opcode == 0x8)
477	            {
478	                obs->gotClose = true;
479	                if (f.payload.size() >= 2)
480	                {
481	                    obs->closeCode =
482	                        (uint16_t)(((uint16_t)(uint8_t) f.payload[0] << 8) |
483	                                   (uint8_t) f.payload[1]);
484	                    obs->closeReason = f.payload.substr(2);
485	                }
486	                if (opts.echoClose)
487	                {
488	                    // Echo the close frame back to complete the closing handshake
489	                    sendAll(fd, encodeFrame(0x8, true, false, f.payload, false));
490	                    break;
491	                }
492	                // Otherwise never answer: the client must give up waiting
493	                // after its closing delay and close the connection anyway.
494	            }
495	            else if (f.opcode == 0xA)
496	            {
497	                obs->pongCount++;
498	            }
499	            else
500	            {
501	                obs->unexpectedFrameCount++;
502	            }
503	        }
504	
505	        close(fd);
506	    }
507	
508	    // A raw server which only sends valid compressed messages, then a normal
509	    // close. Used to check that a WebSocket object can reconnect cleanly
510	    // after a previous connection failed on a decompression error.
511	    void rawServerValidOnlyMain(int listenFd,
512	                                const std::string& text,
513	                                std::shared_ptr<PeerObservation> obs)
514	    {
515	        int fd = accept(listenFd, nullptr, nullptr);
516	        if (fd < 0)
517	        {
518	            obs->harnessError = "accept failed";
519	            return;
520	        }
521	        setRecvTimeout(fd, 15);
522	
523	        std::string request;
524	        if (!readHttpHeaders(fd, request))
525	        {
526	            obs->harnessError = "reading http request failed";
527	            close(fd);
528	            return;
529	        }
530	
531	        std::string key = extractHeader(request, "sec-websocket-key");
532	        char output[29] = {};
533	        WebSocketHandshakeKeyGen::generate(key, output);
534	
535	        std::string response = "HTTP/1.1 101 Switching Protocols\r\n"
536	                               "Upgrade: websocket\r\n"
537	                               "Connection: Upgrade\r\n"
538	                               "Sec-WebSocket-Accept: " +
539	                               std::string(output) +
540	                               "\r\n"
541	                               "Sec-WebSocket-Extensions: permessage-deflate\r\n"
542	                               "\r\n";
543	        if (!sendAll(fd, response))
544	        {
545	            obs->harnessError = "sending handshake response failed";
546	            close(fd);
547	            return;
548	        }
549	
550	        WebSocketPerMessageDeflateCompressor compressor;
551	        compressor.init(15, false);
552	
553	        std::string compressed;
554	        compressor.compress(text, compressed);
555	        obs->validCompressedSizes.push_back(compressed.size());
556	        sendAll(fd, encodeFrame(0x1, true, true, compressed, false));
557	
558	        ix::msleep(200);
559	
560	        // Normal closure
561	        std::string closePayload;
562	        closePayload.push_back((char) (1000 >> 8));
563	        closePayload.push_back((char) (1000 & 0xff));
564	        sendAll(fd, encodeFrame(0x8, true, false, closePayload, false));
565	
566	        Frame f;
567	        while (readFrame(fd, f))
568	        {
569	            if (f.opcode == 0x8)
570	            {
571	                obs->gotClose = true;
572	                break;
573	            }
574	        }
575	
576	        close(fd);
577	    }
578	
579	    void checkValidPrefix(const RecordedEvents& ev,
580	                          const PeerObservation& obs,
581	                          const std::string& bigPayload)
582	    {
583	        std::vector<std::string> expectedMessages = {
584	            "hello", "", bigPayload, "hello", "fragmented valid payload"};
585	        std::vector<bool> expectedBinary = {false, false, true, false, false};
586	
587	        REQUIRE(ev.messages == expectedMessages);
588	        REQUIRE(ev.messageBinary == expectedBinary);
589	        REQUIRE(ev.messageWireSizes == obs.validCompressedSizes);
590	    }
591	
592	    void checkFailure(const RecordedEvents& ev,
593	                      const PeerObservation& obs,
594	                      int expectedFragments,
595	                      int expectedPings)
596	    {
597	        // One Error, no Message for the invalid payload
598	        REQUIRE(ev.errorCount == 1);
599	        REQUIRE(ev.errorDecompression);
600	        REQUIRE(ev.errorStrEmpty);
601	        REQUIRE(ev.errorReason == WebSocketCloseConstants::kDecompressionErrorMessage);
602	        REQUIRE(ev.errorWireSize == obs.invalidPayloadSize);
603	
604	        // The connection was already closing inside the error callback
605	        REQUIRE(ev.readyStateAtError == ix::ReadyState::Closing);
606	        REQUIRE(!ev.sendSucceededAtError);
607	
608	        // Fragment / ping events before the error are still delivered,
609	        // nothing after the error
610	        REQUIRE(ev.fragmentCount == expectedFragments);
611	        REQUIRE(ev.pingCount == expectedPings);
612	        REQUIRE(ev.pongCount == 0);
613	
614	        // A single Close, with the failure code and reason
615	        REQUIRE(ev.closeCount == 1);
616	        REQUIRE(ev.closeCode == kCloseCodeInvalidFramePayloadData);
617	        REQUIRE(ev.closeReason == WebSocketCloseConstants::kDecompressionErrorMessage);
618	        REQUIRE(!ev.closeRemote);
619	
620	        // The peer received the close frame with code 1007, and no pong for
621	        // the ping sent after the error
622	        REQUIRE(obs.harnessError.empty());
623	        REQUIRE(obs.gotClose);
624	        REQUIRE(obs.closeCode == kCloseCodeInvalidFramePayloadData);
625	        REQUIRE(obs.closeReason == WebSocketCloseConstants::kDecompressionErrorMessage);
626	        REQUIRE(obs.pongCount == expectedPings);
627	        REQUIRE(obs.unexpectedFrameCount == 0);
628	    }
629	
630	    void runClientScenario(const ClientScenarioOptions& opts,
631	                           int expectedFragments,
632	                           int expectedPings)
633	    {
634	        int port = getFreePort();
635	        int listenFd = makeListenSocket(port);
636	        REQUIRE(listenFd >= 0);
637	
638	        auto obs = std::make_shared<PeerObservation>();
639	        std::string bigPayload = makeBigPayload();
640	        std::thread serverThread(rawServerMain, listenFd, opts, bigPayload, obs);
641	
642	        RecordedEvents ev;
643	        ix::WebSocket ws;
644	        {
645	            std::stringstream ss;
646	            ss << "ws://localhost:" << port << "/";
647	            ws.setUrl(ss.str());
648	        }
649	        ws.enablePerMessageDeflate();
650	        ws.disableAutomaticReconnection();
651	        ws.setOnMessageCallback(
652	            [&ws, &ev](const ix::WebSocketMessagePtr& msg) { recordEvent(ws, ev, msg); });
653	        ws.start();
654	
655	        REQUIRE(waitFor([&] {
656	            std::lock_guard<std::mutex> lock(ev.mutex);
657	            return ev.closeCount >= 1;
658	        },
659	                        15000));
660	
661	        ws.stop();
662	        serverThread.join();
663	        close(listenFd);
664	
665	        checkValidPrefix(ev, *obs, bigPayload);
666	        checkFailure(ev, *obs, expectedFragments, expectedPings);
667	    }
