762	        // Second connection on the same WebSocket object: valid traffic only
763	        RecordedEvents ev2;
764	        int port2 = getFreePort();
765	        int listenFd2 = makeListenSocket(port2);
766	        REQUIRE(listenFd2 >= 0);
767	
768	        auto obs2 = std::make_shared<PeerObservation>();
769	        std::thread serverThread2(rawServerValidOnlyMain, listenFd2, "hello again", obs2);
770	
771	        {
772	            std::stringstream ss;
773	            ss << "ws://localhost:" << port2 << "/";
774	            ws.setUrl(ss.str());
775	        }
776	        ws.setOnMessageCallback(
777	            [&ws, &ev2](const ix::WebSocketMessagePtr& msg) { recordEvent(ws, ev2, msg); });
778	        ws.start();
779	
780	        REQUIRE(waitFor([&] {
781	            std::lock_guard<std::mutex> lock(ev2.mutex);
782	            return ev2.closeCount >= 1;
783	        },
784	                        15000));
