790	        REQUIRE(ev2.openCount == 1);
791	        REQUIRE(ev2.messages == std::vector<std::string>{"hello again"});
792	        REQUIRE(ev2.messageWireSizes == obs2->validCompressedSizes);
793	        REQUIRE(ev2.errorCount == 0);
794	        REQUIRE(ev2.closeCount == 1);
795	        REQUIRE(ev2.closeCode == 1000);
796	    }
797	}
