            ws.setUrl(ss.str());
        }
        ws.enablePerMessageDeflate();
        ws.disableAutomaticReconnection();
        ws.setOnMessageCallback(
            [&ws, &ev](const ix::WebSocketMessagePtr& msg) { recordEvent(ws, ev, msg); });
        ws.start();

        REQUIRE(waitFor([&] {
            std::lock_guard<std::mutex> lock(ev.mutex);
