TEST_CASE("per-message-deflate-invalid-server", "[zlib][pmd-invalid]")
{
    SECTION("a server receiving an invalid compressed payload fails the message and closes")
    {
        int port = getFreePort();
        ix::WebSocketServer server(port);

        RecordedEvents ev;
        server.setOnClientMessageCallback(
            [&ev](std::shared_ptr<ConnectionState> /*connectionState*/,
                  WebSocket& webSocket,
                  const ix::WebSocketMessagePtr& msg) {
                recordEvent(webSocket, ev, msg);
            });

        auto res = server.listen();
        REQUIRE(res.first);
        server.start();

        // Raw client talking to the ix server
        int fd = connectTo(port);
        REQUIRE(fd >= 0);
        setRecvTimeout(fd, 15);

        std::string request = "GET / HTTP/1.1\r\n"
                              "Host: localhost\r\n"
                              "Upgrade: websocket\r\n"
                              "Connection: Upgrade\r\n"
                              "Sec-WebSocket-Version: 13\r\n"
                              "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                              "Sec-WebSocket-Extensions: permessage-deflate\r\n"
                              "\r\n";
        REQUIRE(sendAll(fd, request));

        std::string response;
        REQUIRE(readHttpHeaders(fd, response));
        REQUIRE(response.find("101") != std::string::npos);
        REQUIRE(response.find("permessage-deflate") != std::string::npos);

        WebSocketPerMessageDeflateCompressor compressor;
        compressor.init(15, false);

        std::string compressed;
        compressor.compress(std::string("hello"), compressed);
        size_t validCompressedSize = compressed.size();

        // A valid message, then an invalid one (clients must mask)
        REQUIRE(sendAll(fd, encodeFrame(0x1, true, true, compressed, true)));
        REQUIRE(sendAll(fd, encodeFrame(0x1, true, true, std::string("\x07", 1), true)));

        ix::msleep(300);

        // Trailing traffic, must be dropped
        std::string compressedWorld;
        compressor.compress(std::string("world"), compressedWorld);
        REQUIRE(sendAll(fd, encodeFrame(0x1, true, true, compressedWorld, true)));
        REQUIRE(sendAll(fd, encodeFrame(0x9, true, false, "p3", true)));

        // The server must close with 1007 and not reply to the ping
        PeerObservation obs;
        Frame f;
        while (readFrame(fd, f))
        {
            if (f.opcode == 0x8)
            {
                obs.gotClose = true;
                if (f.payload.size() >= 2)
                {
                    obs.closeCode =
                        (uint16_t)(((uint16_t)(uint8_t) f.payload[0] << 8) |
                                   (uint8_t) f.payload[1]);
                    obs.closeReason = f.payload.substr(2);
                }
                // Echo the close frame back
                REQUIRE(sendAll(fd, encodeFrame(0x8, true, false, f.payload, true)));
                break;
            }
            else if (f.opcode == 0xA)
            {
                obs.pongCount++;
            }
            else
            {
                obs.unexpectedFrameCount++;
            }
        }
        close(fd);

        REQUIRE(waitFor([&] {
            std::lock_guard<std::mutex> lock(ev.mutex);
            return ev.closeCount >= 1;
        },
                        15000));

        server.stop();

        // The valid message was delivered, the invalid one was not
        REQUIRE(ev.messages == std::vector<std::string>{"hello"});
        REQUIRE(ev.messageWireSizes == std::vector<size_t>{validCompressedSize});

        REQUIRE(ev.errorCount == 1);
        REQUIRE(ev.errorDecompression);
        REQUIRE(ev.errorStrEmpty);
        REQUIRE(ev.errorReason == WebSocketCloseConstants::kDecompressionErrorMessage);
        REQUIRE(ev.errorWireSize == 1);
        REQUIRE(ev.readyStateAtError == ix::ReadyState::Closing);
        REQUIRE(!ev.sendSucceededAtError);

        REQUIRE(ev.pingCount == 0);
        REQUIRE(ev.closeCount == 1);
        REQUIRE(ev.closeCode == kCloseCodeInvalidFramePayloadData);
        REQUIRE(ev.closeReason == WebSocketCloseConstants::kDecompressionErrorMessage);
        REQUIRE(!ev.closeRemote);

        REQUIRE(obs.gotClose);
        REQUIRE(obs.closeCode == kCloseCodeInvalidFramePayloadData);
        REQUIRE(obs.closeReason == WebSocketCloseConstants::kDecompressionErrorMessage);
        REQUIRE(obs.pongCount == 0);
        REQUIRE(obs.unexpectedFrameCount == 0);
    }
}

#!/usr/bin/env bash
set -u
run() {
    "$@"
    local result=$?
    printf 'exitCode=%d\n' "$result"
    return "$result"
}
status=0
run bash -s <<'PMD_PREPARE'
set -eu
bash demo/prepare.sh
for asset in demo/pmd_peer.hpp demo/pmd_receive.cpp; do
    if git ls-files --error-unmatch "$asset" >/dev/null 2>&1; then
        printf 'Refusing to overwrite tracked asset: %s\n' "$asset" >&2
        exit 2
    fi
done
old='    setup(bytes.size() > 3, "split-read fixture is too short");'
matches=$(grep -Fxc "$old" demo/pmd_peer.hpp || true)
if [ "$matches" != 1 ]; then
    printf 'Expected exactly one original split-read fixture guard.\n' >&2
    exit 2
fi
sed -i 's/bytes\.size() > 3, "split-read fixture is too short"/bytes.size() >= 3, "split-read fixture is too short"/' demo/pmd_peer.hpp
grep -Fqx '    setup(bytes.size() >= 3, "split-read fixture is too short");' demo/pmd_peer.hpp
cat > demo/pmd_receive.cpp <<'CPP'
#include "pmd_peer.hpp"
#include <csignal>
int main(int argc, char** argv) {
    std::signal(SIGPIPE, SIG_IGN);
    ix::initNetSystem();
    if (argc != 2) {
        std::cerr << "Usage: ws_receive corrupt|corrupt-split|compressed\n";
        return 2;
    }
    std::string argument(argv[1]);
    std::string mode;
    if (argument == "corrupt") mode = "bad07";
    else if (argument == "corrupt-split") mode = "bad_split";
    else if (argument == "compressed") mode = "good_empty";
    else {
        std::cerr << "Usage: ws_receive corrupt|corrupt-split|compressed\n";
        return 2;
    }
    try {
        pmd::Plan plan{false, false, mode};
        pmd::Exchange result = pmd::receive(plan, nullptr, true);
        return result.closedNaturally ? 0 : 1;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 2;
    }
}
CPP
PMD_PREPARE
prepared=$?
if [ "$prepared" -ne 0 ]; then
    exit "$prepared"
fi
run cmake --build demo/build --target receive_checks ws_receive IXWebSocketPerMessageDeflateCompressorTest -j2
built=$?
if [ "$built" -eq 0 ]; then
    run demo/build/receive_checks --list
    listed=$?
    if [ "$listed" -ne 0 ]; then status=1; fi
    run demo/build/receive_checks all
    tested=$?
    if [ "$tested" -ne 0 ]; then status=1; fi
    listing=$(ctest --test-dir demo/build/sealed/test -N -R '^IXWebSocketPerMessageDeflateCompressorTest$' 2>&1)
    discovered=$?
    printf '%s\n' "$listing"
    printf 'discoveryExitCode=%d\n' "$discovered"
    if [ "$discovered" -eq 0 ] && [[ "$listing" =~ Total\ Tests:\ 1([^0-9]|$) ]]; then
        run ctest --test-dir demo/build/sealed/test -R '^IXWebSocketPerMessageDeflateCompressorTest$' --output-on-failure -V
        regression=$?
        if [ "$regression" -ne 0 ]; then status=1; fi
    else
        printf 'Expected exactly one discovered compression regression target.\n' >&2
        status=1
    fi
else
    status=1
fi
run cmake --build demo/build --target legacy_callback -j2
compatible=$?
if [ "$compatible" -eq 0 ]; then
    run demo/build/legacy_callback
    legacy=$?
    if [ "$legacy" -ne 0 ]; then status=1; fi
else
    status=1
fi
exit "$status"

