208	    return result + reason;
209	}
210	struct Channel {
211	    Fd fd;
212	    SSL_CTX* context = nullptr;
213	    SSL* ssl = nullptr;
214	    explicit Channel(int descriptor) : fd(descriptor) { timeoutSocket(fd.value); }
215	    ~Channel() {
216	        if (ssl) SSL_free(ssl);
217	        if (context) SSL_CTX_free(context);
218	    }
219	    void encrypt(bool server) {
220	        context = SSL_CTX_new(TLS_method());
221	        setup(context != nullptr, "SSL_CTX_new failed");
222	        SSL_CTX_set_verify(context, SSL_VERIFY_NONE, nullptr);
223	        if (server) {
224	            setup(SSL_CTX_use_certificate_file(context, "test/.certs/trusted-server-crt.pem", SSL_FILETYPE_PEM) == 1, "loading TLS fixture certificate failed");
225	            setup(SSL_CTX_use_PrivateKey_file(context, "test/.certs/trusted-server-key.pem", SSL_FILETYPE_PEM) == 1, "loading TLS fixture key failed");
226	            setup(SSL_CTX_check_private_key(context) == 1, "TLS fixture key does not match certificate");
227	        }
228	        ssl = SSL_new(context);
229	        setup(ssl != nullptr && SSL_set_fd(ssl, fd.value) == 1, "SSL setup failed");
230	        setup((server ? SSL_accept(ssl) : SSL_connect(ssl)) == 1, "local TLS handshake failed");
231	    }
232	    void write(const std::string& bytes) {
233	        size_t sent = 0;
234	        while (sent < bytes.size()) {
235	            int amount = static_cast<int>(std::min<size_t>(16384, bytes.size() - sent));
236	            int n = ssl ? SSL_write(ssl, bytes.data() + sent, amount)
237	                        : static_cast<int>(::send(fd.value, bytes.data() + sent, amount, MSG_NOSIGNAL));
238	            setup(n > 0, "peer write failed before all requested bytes were sent");
239	            sent += static_cast<size_t>(n);
240	        }
241	    }
242	    int read(char* bytes, size_t length, int milliseconds) {
243	        if (!ssl || SSL_pending(ssl) == 0) {
244	            pollfd p;
245	            p.fd = fd.value;
246	            p.events = POLLIN;
247	            p.revents = 0;
248	            int ready = ::poll(&p, 1, std::max(1, milliseconds));
249	            if (ready == 0) return 0;
250	            setup(ready > 0, "peer poll failed");
251	        }
252	        int n = ssl ? SSL_read(ssl, bytes, static_cast<int>(length))
253	                    : static_cast<int>(::recv(fd.value, bytes, length, 0));
254	        return n > 0 ? n : -1;
255	    }
256	    bool exact(char* bytes, size_t length, int milliseconds = 2000) {
257	        size_t received = 0;
258	        auto until = Clock::now() + std::chrono::milliseconds(milliseconds);
259	        while (received < length) {
260	            int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(until - Clock::now()).count());
261	            if (remaining <= 0) return false;
262	            int n = read(bytes + received, length - received, remaining);
263	            if (n <= 0) return false;
264	            received += static_cast<size_t>(n);
265	        }
266	        return true;
267	    }
268	    std::string headers() {
269	        std::string result;
270	        auto until = Clock::now() + std::chrono::seconds(3);
271	        while (result.find("\r\n\r\n") == std::string::npos) {
272	            char c;
273	            int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(until - Clock::now()).count());
274	            setup(remaining > 0 && read(&c, 1, remaining) == 1, "HTTP upgrade headers incomplete or timed out");
275	            result.push_back(c);
276	            setup(result.size() < 65536, "HTTP upgrade headers exceed fixture limit");
277	        }
278	        return result;
279	    }
280	    int next(Frame& result, int milliseconds) {
281	        char first;
282	        int n = read(&first, 1, milliseconds);
283	        if (n <= 0) return n;
284	        unsigned char h[2];
285	        h[0] = static_cast<unsigned char>(first);
286	        setup(exact(reinterpret_cast<char*>(&h[1]), 1), "incomplete outbound frame header");
287	        result.opcode = h[0] & 15;
288	        result.fin = (h[0] & 128) != 0;
289	        result.compressed = (h[0] & 64) != 0;
290	        result.masked = (h[1] & 128) != 0;
291	        uint64_t length = h[1] & 127;
292	        if (length == 126 || length == 127) {
293	            int width = length == 126 ? 2 : 8;
294	            unsigned char extended[8] = {};
295	            setup(exact(reinterpret_cast<char*>(extended), width), "incomplete outbound extended frame length");
296	            length = 0;
297	            for (int i = 0; i < width; ++i) length = (length << 8) | extended[i];
298	        }
299	        setup(length <= 1024 * 1024, "outbound frame exceeds fixture limit");
300	        unsigned char mask[4] = {};
301	        if (result.masked) setup(exact(reinterpret_cast<char*>(mask), 4), "incomplete outbound mask");
302	        result.payload.assign(static_cast<size_t>(length), '\0');
303	        if (length) setup(exact(&result.payload[0], static_cast<size_t>(length)), "incomplete outbound payload");
304	        if (result.masked) for (size_t i = 0; i < result.payload.size(); ++i) result.payload[i] = static_cast<char>(static_cast<unsigned char>(result.payload[i]) ^ mask[i % 4]);
305	        return 1;
306	    }
307	};
308	inline std::string header(const std::string& input, const std::string& key) {
309	    std::string haystack = lower(input);
310	    size_t pos = haystack.find("\r\n" + lower(key) + ":");
311	    if (pos == std::string::npos) return "";
312	    pos += key.size() + 3;
313	    while (pos < input.size() && input[pos] == ' ') ++pos;
314	    size_t end = input.find("\r\n", pos);
315	    return input.substr(pos, end - pos);
316	}
317	inline std::string upgradeServer(Channel& channel, bool compression) {
318	    std::string request = channel.headers();
319	    std::string key = header(request, "Sec-WebSocket-Key");
320	    setup(!key.empty(), "client upgrade request has no WebSocket key");
321	    if (compression) setup(header(request, "Sec-WebSocket-Extensions").find("permessage-deflate") != std::string::npos, "client did not offer permessage-deflate");
322	    char accept[29] = {};
323	    WebSocketHandshakeKeyGen::generate(key, accept);
324	    std::string response = "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: " + std::string(accept, 28) + "\r\n";
325	    if (compression) response += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
326	    channel.write(response + "\r\n");
327	    return request;
328	}
329	inline std::string upgradeClient(Channel& channel, int port, bool compression) {
330	    std::string request = "GET / HTTP/1.1\r\nHost: localhost:" + std::to_string(port)
331	        + "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n";
332	    if (compression) request += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
333	    channel.write(request + "\r\n");
334	    std::string response = channel.headers();
335	    setup(response.find("HTTP/1.1 101 ") == 0, "server rejected HTTP upgrade: " + response);
336	    setup(header(response, "Sec-WebSocket-Accept") == "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", "server upgrade accept key differs from RFC fixture");
337	    if (compression) setup(header(response, "Sec-WebSocket-Extensions").find("permessage-deflate") != std::string::npos, "server did not negotiate permessage-deflate");
338	    return response;
339	}
340	struct Deflater {
341	    z_stream stream;
342	    Deflater() {
343	        std::memset(&stream, 0, sizeof(stream));
344	        setup(deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY) == Z_OK, "fixture deflate initialization failed");
345	    }
346	    ~Deflater() { deflateEnd(&stream); }
347	    std::string encode(const std::string& body) {
348	        stream.next_in = reinterpret_cast<Bytef*>(const_cast<char*>(body.data()));
349	        stream.avail_in = static_cast<uInt>(body.size());
350	        std::string result;
351	        do {
352	            char buffer[8192];
353	            stream.next_out = reinterpret_cast<Bytef*>(buffer);
354	            stream.avail_out = sizeof(buffer);
355	            setup(deflate(&stream, Z_SYNC_FLUSH) == Z_OK, "fixture deflate failed");
356	            result.append(buffer, sizeof(buffer) - stream.avail_out);
357	        } while (stream.avail_in || stream.avail_out == 0);
358	        const std::string tail("\x00\x00\xff\xff", 4);
359	        setup(result.size() >= 4 && result.compare(result.size() - 4, 4, tail) == 0, "fixture compression has no sync-flush tail");
360	        result.resize(result.size() - 4);
361	        return result;
362	    }
363	};
364	inline std::string body(size_t length, bool binary) {
365	    std::string result;
366	    uint32_t state = 0x6a09e667;
367	    for (size_t i = 0; i < length; ++i) {
368	        state ^= state << 13;
369	        state ^= state >> 17;
370	        state ^= state << 5;
371	        result.push_back(binary ? static_cast<char>(state & 255) : static_cast<char>('!' + state % 90));
372	    }
373	    return result;
374	}
375	inline std::string invalidPayload(bool partial) {
376	    if (!partial) return std::string(1, '\x07');
377	    const size_t length = 40960;
378	    std::string result(1, '\0');
379	    uint16_t n = static_cast<uint16_t>(length);
380	    uint16_t inverse = static_cast<uint16_t>(~n);
381	    result.push_back(static_cast<char>(n & 255));
382	    result.push_back(static_cast<char>(n >> 8));
383	    result.push_back(static_cast<char>(inverse & 255));
384	    result.push_back(static_cast<char>(inverse >> 8));
385	    result.append(length, 'A');
386	    result.push_back('\x07');
387	    return result;
388	}
389	inline void validateInvalidFixture(const std::string& payload, bool partial) {
390	    z_stream stream;
391	    std::memset(&stream, 0, sizeof(stream));
392	    setup(inflateInit2(&stream, -15) == Z_OK, "fixture inflate initialization failed");
393	    std::string input = payload + std::string("\x00\x00\xff\xff", 4);
394	    stream.next_in = reinterpret_cast<Bytef*>(&input[0]);
395	    stream.avail_in = static_cast<uInt>(input.size());
396	    int status = Z_OK;
397	    size_t produced = 0;
398	    do {
399	        unsigned char buffer[8192];
400	        stream.next_out = buffer;
401	        stream.avail_out = sizeof(buffer);
402	        status = inflate(&stream, Z_SYNC_FLUSH);
403	        produced += sizeof(buffer) - stream.avail_out;
404	    } while (status == Z_OK && (stream.avail_in || stream.avail_out == 0));
405	    inflateEnd(&stream);
406	    setup(status == Z_DATA_ERROR, "invalid fixture was not rejected by real zlib");
407	    setup(!partial || produced >= 40960, "partial-output fixture did not produce 40KiB before rejection");
408	}
409	struct Input { std::string body; size_t wire; bool binary; };
410	struct Checkpoint { bool reached; std::vector<Event> events; };
411	struct Exchange {
412	    std::vector<Event> events;
413	    std::vector<Input> expected;
414	    std::vector<Checkpoint> pending;
415	    std::vector<Frame> outbound;
416	    std::vector<std::string> expectedPings;
417	    std::vector<std::string> expectedPongs;
418	    size_t badWire = 0;
419	    bool closedNaturally = false, eof = false, closeSent = false;
420	    std::string closeWirePayload;
421	    Clock::time_point echoedAt;
422	    bool echoed = false;
423	};
424	struct Plan {
425	    bool server, binary;
426	    std::string mode;
427	    bool bad() const { return mode.compare(0, 3, "bad") == 0; }
428	    bool tls() const { return mode == "good_tls" || mode == "bad_tls"; }
429	    bool fragmented() const { return mode == "good_fragmented" || mode == "bad_fragmented"; }
430	    bool compression() const { return mode != "plain_disabled"; }
431	};
432	struct Finally {
433	    std::function<void()> function;
