436	};
437	inline void checkpoint(Events& events, Exchange& result, size_t messages, size_t fragments, size_t pings, size_t pongs) {
438	    bool reached = events.wait([=](const std::vector<Event>& current) {
439	        return count(current, Type::Fragment) >= fragments && count(current, Type::Message) >= messages
440	            && count(current, Type::Ping) >= pings && count(current, Type::Pong) >= pongs;
441	    });
442	    result.pending.push_back(Checkpoint{reached, events.snapshot()});
443	}
444	inline void splitWrite(Channel& channel, const std::string& bytes, Events& events, Exchange& result) {
445	    setup(bytes.size() >= 3, "split-read fixture is too short");
446	    channel.write(bytes.substr(0, 1));
447	    std::this_thread::sleep_for(std::chrono::milliseconds(15));
448	    result.pending.push_back(Checkpoint{true, events.snapshot()});
449	    size_t headerLength = 2;
450	    unsigned char second = static_cast<unsigned char>(bytes[1]);
451	    if ((second & 127) == 126) headerLength += 2;
452	    if ((second & 127) == 127) headerLength += 8;
453	    if (second & 128) headerLength += 4;
454	    channel.write(bytes.substr(1, headerLength - 1));
455	    std::this_thread::sleep_for(std::chrono::milliseconds(15));
456	    result.pending.push_back(Checkpoint{true, events.snapshot()});
457	    size_t position = headerLength;
458	    if (bytes.size() - position > 1) {
459	        size_t amount = (bytes.size() - position) / 2;
460	        channel.write(bytes.substr(position, amount));
461	        position += amount;
462	        std::this_thread::sleep_for(std::chrono::milliseconds(15));
463	        result.pending.push_back(Checkpoint{true, events.snapshot()});
464	    }
465	    channel.write(bytes.substr(position));
466	}
467	inline Exchange receive(const Plan& plan, ix::WebSocket* reused = nullptr, bool verbose = false) {
468	    Events events(verbose);
469	    ix::WebSocket local;
470	    ix::WebSocket& websocket = reused ? *reused : local;
471	    std::unique_ptr<ix::WebSocketServer> server;
472	    std::unique_ptr<Fd> listening;
473	    int port = 0;
474	    Finally cleanup([&] {
475	        if (server) server->stop();
476	        else {
477	            websocket.stop();
478	            websocket.setOnMessageCallback([](const ix::WebSocketMessagePtr&) {});
479	        }
480	    });
481	    if (plan.server) {
482	        port = ix::getFreePort();
483	        setup(port > 0, "could not allocate local product-server port");
484	        server.reset(new ix::WebSocketServer(port, "127.0.0.1", 4, 4, 2, AF_INET, -1));
485	        if (!plan.compression()) server->disablePerMessageDeflate();
486	        if (plan.tls()) {
487	            ix::SocketTLSOptions options;
488	            options.tls = true;
489	            options.certFile = "test/.certs/trusted-server-crt.pem";
490	            options.keyFile = "test/.certs/trusted-server-key.pem";
491	            options.caFile = "NONE";
492	            server->setTLSOptions(options);
493	        }
494	        server->setOnClientMessageCallback([&](std::shared_ptr<ix::ConnectionState>, ix::WebSocket& socket, const ix::WebSocketMessagePtr& message) {
495	            if (message->type == Type::Open) socket.disableAutomaticReconnection();
496	            events.record(socket, message);
497	        });
498	        auto status = server->listen();
499	        setup(status.first, "product server listen failed: " + status.second);
500	        server->start();
501	    } else {
502	        listening.reset(new Fd(listener(port)));
503	        websocket.disableAutomaticReconnection();
504	        websocket.setHandshakeTimeout(2);
505	        websocket.setPingInterval(-1);
506	        websocket.setPerMessageDeflateOptions(ix::WebSocketPerMessageDeflateOptions(plan.compression(), false, false, 15, 15, false));
507	        ix::SocketTLSOptions options;
508	        options.caFile = "NONE";
509	        options.disable_hostname_validation = true;
510	        websocket.setTLSOptions(options);
511	        websocket.setUrl(std::string(plan.tls() ? "wss" : "ws") + "://localhost:" + std::to_string(port) + "/");
512	        websocket.setOnMessageCallback([&](const ix::WebSocketMessagePtr& message) { events.record(websocket, message); });
513	        websocket.start();
514	    }
515	    std::unique_ptr<Channel> channel(new Channel(plan.server ? connectPeer(port) : acceptPeer(listening->value)));
516	    if (plan.tls()) channel->encrypt(!plan.server);
517	    std::string handshake = plan.server ? upgradeClient(*channel, port, plan.compression()) : upgradeServer(*channel, plan.compression());
518	    if (plan.compression()) {
519	        std::string extension = header(handshake, "Sec-WebSocket-Extensions");
520	        setup(extension.find("client_no_context_takeover") == std::string::npos
521	            && extension.find("server_no_context_takeover") == std::string::npos, "context-takeover fixture negotiated a reset context");
522	    }
523	    setup(events.wait([](const std::vector<Event>& current) { return count(current, Type::Open) == 1; }), "Open callback did not arrive after completed upgrade");
524	    Exchange result;
525	    Deflater compressor;
526	    unsigned opcode = plan.binary ? 2 : 1;
527	    auto packet = [&](unsigned op, bool final, bool compressed, const std::string& payload) {
528	        return frame(op, final, compressed, payload, plan.server);
529	    };
530	    auto compressedMessage = [&](const std::string& value, bool expected) {
531	        std::string payload = compressor.encode(value);
532	        if (expected) result.expected.push_back(Input{value, payload.size(), plan.binary});
533	        return packet(opcode, true, true, payload);
534	    };
535	    auto controls = [&](const std::string& value) {
536	        result.expectedPings.push_back(value);
537	        result.expectedPongs.push_back(value);
538	        return packet(9, true, false, value) + packet(10, true, false, value);
539	    };
540	    auto following = [&]() {
541	        std::string a = compressor.encode("next");
542	        std::string b = compressor.encode("continued");
543	        size_t split = std::max<size_t>(1, b.size() / 2);
544	        return packet(opcode, true, true, a)
545	            + packet(opcode, false, true, b.substr(0, split))
546	            + packet(9, true, false, "later") + packet(10, true, false, "later")
547	            + packet(0, true, false, b.substr(split));
548	    };
549	    std::string late;
550	    if (plan.bad()) {
551	        bool partial = plan.mode == "bad_partial" || plan.mode == "bad_fragmented" || plan.mode == "bad_tls";
552	        std::string bad = invalidPayload(partial);
553	        validateInvalidFixture(bad, partial);
554	        result.badWire = bad.size();
555	        std::string prefix = compressedMessage("ready", true) + controls("heartbeat");
556	        late = following();
557	        std::ostringstream input;
558	        input << "receive compressed " << (plan.binary ? "BINARY" : "TEXT") << " payloadBytes=" << bad.size();
559	        if (bad.size() == 1) input << " payload=07";
560	        input << " followingFrameBytes=" << late.size();
561	        trace(verbose, input.str());
562	        if (plan.fragmented()) {
563	            size_t one = bad.size() / 3;
564	            size_t two = (bad.size() * 2) / 3;
565	            channel->write(prefix + packet(opcode, false, true, bad.substr(0, one)));
566	            checkpoint(events, result, 1, 1, 1, 1);
567	            channel->write(controls("fragment") + packet(0, false, false, bad.substr(one, two - one)));
568	            checkpoint(events, result, 1, 2, 2, 2);
569	            channel->write(packet(0, true, false, bad.substr(two)) + late);
570	        } else if (plan.mode == "bad_split") {
571	            channel->write(prefix);
572	            checkpoint(events, result, 1, 0, 1, 1);
573	            splitWrite(*channel, packet(opcode, true, true, bad), events, result);
574	            channel->write(late);
575	        } else channel->write(prefix + packet(opcode, true, true, bad) + late);
576	    } else {
577	        std::string value;
578	        if (plan.mode == "good_empty") value = "";
579	        else if (plan.mode == "good_context") value = body(6000, plan.binary);
580	        else if (plan.mode == "plain_negotiated" || plan.mode == "plain_disabled") value = plan.binary ? std::string("plain\0binary\xff", 13) : "plain text";
581	        else value = body(plan.mode == "good_split" ? 6000 : 45056, plan.binary);
582	        if (plan.mode == "plain_negotiated" || plan.mode == "plain_disabled") {
583	            result.expected.push_back(Input{value, value.size(), plan.binary});
584	            channel->write(packet(opcode, true, false, value));
585	        } else if (plan.mode == "good_context") {
586	            std::string bytes;
587	            for (int i = 0; i < 3; ++i) bytes += compressedMessage(value, true);
588	            channel->write(bytes);
589	        } else {
590	            std::string payload = compressor.encode(value);
591	            result.expected.push_back(Input{value, payload.size(), plan.binary});
592	            if (plan.fragmented()) {
593	                size_t one = payload.size() / 3;
594	                size_t two = (payload.size() * 2) / 3;
595	                channel->write(packet(opcode, false, true, payload.substr(0, one)));
596	                checkpoint(events, result, 0, 1, 0, 0);
597	                channel->write(controls("fragment") + packet(0, false, false, payload.substr(one, two - one)));
598	                checkpoint(events, result, 0, 2, 1, 1);
599	                channel->write(packet(0, true, false, payload.substr(two)));
600	            } else if (plan.mode == "good_split") splitWrite(*channel, packet(opcode, true, true, payload), events, result);
601	            else channel->write(packet(opcode, true, true, payload));
602	        }
603	        events.wait([&](const std::vector<Event>& current) { return count(current, Type::Message) >= result.expected.size() || count(current, Type::Error) > 0; });
604	        channel->write(packet(8, true, false, closePayload(1000, "finished")));
605	    }
606	    auto deadline = Clock::now() + std::chrono::seconds(2);
607	    bool sentAfterClose = false;
608	    while (Clock::now() < deadline) {
609	        Frame received;
610	        int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(deadline - Clock::now()).count());
611	        int status = channel->next(received, remaining);
612	        if (status < 0) { result.eof = true; break; }
613	        if (status == 0) break;
614	        result.outbound.push_back(received);
615	        if (received.opcode == 8) {
616	            if (!result.closeSent) result.closeWirePayload = received.payload;
617	            result.closeSent = true;
618	            std::ostringstream line;
619	            line << "outbound Close";
620	            if (received.payload.size() >= 2) {
621	                unsigned code = (static_cast<unsigned char>(received.payload[0]) << 8) | static_cast<unsigned char>(received.payload[1]);
622	                line << " code=" << code << " reason=" << quoted(received.payload.substr(2));
623	            } else line << " payload=" << quoted(received.payload);
624	            trace(verbose, line.str());
625	            if (plan.bad() && !sentAfterClose) {
626	                channel->write(late);
627	                sentAfterClose = true;
628	                if (plan.mode != "bad_timeout") {
629	                    channel->write(packet(8, true, false, received.payload));
630	                    result.echoedAt = Clock::now();
631	                    result.echoed = true;
632	                }
633	            }
634	        } else {
635	            trace(verbose, "outbound opcode=" + std::to_string(received.opcode) + " payload=" + quoted(received.payload));
636	        }
637	    }
638	    result.closedNaturally = events.wait([](const std::vector<Event>& current) { return count(current, Type::Close) >= 1; }, 1000);
639	    channel.reset();
640	    cleanup.function();
641	    cleanup.function = nullptr;
642	    result.events = events.snapshot();
643	    return result;
644	}
