using Clock = std::chrono::steady_clock;
using Type = ix::WebSocketMessageType;
struct SetupError : std::runtime_error { using std::runtime_error::runtime_error; };
inline void setup(bool value, const std::string& detail) {
    if (!value) throw SetupError(detail);
}
inline std::string lower(std::string value) {
    for (char& c : value) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return value;
}
inline std::string quoted(const std::string& value) {
    std::ostringstream out;
    out << '"';
    for (unsigned char c : value) {
        if (c == '"' || c == '\\') out << '\\' << static_cast<char>(c);
        else if (c >= 32 && c < 127) out << static_cast<char>(c);
        else out << "\\x" << std::hex << std::setw(2) << std::setfill('0') << unsigned(c) << std::dec;
    }
    out << '"';
    return out.str();
}
inline void trace(bool enabled, const std::string& value) {
    if (!enabled) return;
    static std::mutex mutex;
    std::lock_guard<std::mutex> lock(mutex);
    std::cout << value << std::endl;
}
inline const char* name(Type type) {
    switch (type) {
        case Type::Open: return "Open";
        case Type::Message: return "Message";
        case Type::Fragment: return "Fragment";
        case Type::Ping: return "Ping";
        case Type::Pong: return "Pong";
        case Type::Error: return "Error";
        case Type::Close: return "Close";
        default: return "Unknown";
    }
}
struct Event {
    Type type;
    std::string body, reason;
    size_t wire = 0;
    bool binary = false, decompression = false, sendSucceeded = false;
    ix::ReadyState state = ix::ReadyState::Closed;
    uint16_t code = 0;
    Clock::time_point at;
};
inline size_t count(const std::vector<Event>& events, Type type) {
    return static_cast<size_t>(std::count_if(events.begin(), events.end(), [type](const Event& e) { return e.type == type; }));
}
struct Events {
    std::mutex mutex;
    std::condition_variable changed;
    std::vector<Event> values;
    bool verbose;
    explicit Events(bool v = false) : verbose(v) {}
    void record(ix::WebSocket& socket, const ix::WebSocketMessagePtr& message) {
        Event e;
        e.type = message->type;
        e.body = message->str;
        e.wire = message->wireSize;
        e.binary = message->binary;
        e.decompression = message->errorInfo.decompressionError;
        e.reason = e.type == Type::Close ? message->closeInfo.reason : message->errorInfo.reason;
        e.code = message->closeInfo.code;
        e.state = socket.getReadyState();
        e.at = Clock::now();
        if (e.type == Type::Error) e.sendSucceeded = socket.send("retry").success;
        {
            std::lock_guard<std::mutex> lock(mutex);
            values.push_back(e);
        }
        std::ostringstream line;
        line << name(e.type) << " str=" << quoted(e.body) << " wireSize=" << e.wire
             << " binary=" << std::boolalpha << e.binary;
        if (e.type == Type::Error) line << " decompressionError=" << e.decompression
            << " reason=" << quoted(e.reason) << " state=" << ix::WebSocket::readyStateToString(e.state)
            << " send.success=" << e.sendSucceeded;
        if (e.type == Type::Close) line << " code=" << e.code << " reason=" << quoted(e.reason);
        trace(verbose, line.str());
        changed.notify_all();
    }
    std::vector<Event> snapshot() {
        std::lock_guard<std::mutex> lock(mutex);
        return values;
    }
    bool wait(const std::function<bool(const std::vector<Event>&)>& predicate, int milliseconds = 2000) {
        std::unique_lock<std::mutex> lock(mutex);
        return changed.wait_for(lock, std::chrono::milliseconds(milliseconds), [&] { return predicate(values); });
    }
};
struct Fd {
    int value;
    explicit Fd(int v = -1) : value(v) {}
    ~Fd() { if (value >= 0) ::close(value); }
    Fd(const Fd&) = delete;
    Fd& operator=(const Fd&) = delete;
};
inline void timeoutSocket(int fd) {
    timeval timeout;
    timeout.tv_sec = 3;
    timeout.tv_usec = 0;
    setup(setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) == 0, "setting peer receive timeout failed");
    setup(setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) == 0, "setting peer send timeout failed");
}
inline int listener(int& port) {
    Fd fd(::socket(AF_INET, SOCK_STREAM, 0));
    setup(fd.value >= 0, "creating listener failed");
    int one = 1;
    setsockopt(fd.value, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
    sockaddr_in address;
    std::memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    address.sin_port = 0;
    setup(::bind(fd.value, reinterpret_cast<sockaddr*>(&address), sizeof(address)) == 0, "binding loopback listener failed");
    setup(::listen(fd.value, 2) == 0, "listen failed");
    socklen_t size = sizeof(address);
    setup(getsockname(fd.value, reinterpret_cast<sockaddr*>(&address), &size) == 0, "getsockname failed");
    port = ntohs(address.sin_port);
    int result = fd.value;
    fd.value = -1;
    return result;
}
inline int acceptPeer(int listening) {
    pollfd p;
    p.fd = listening;
    p.events = POLLIN;
    p.revents = 0;
    setup(::poll(&p, 1, 3000) > 0, "product did not connect to loopback listener within 3 seconds");
    int fd = ::accept(listening, nullptr, nullptr);
    setup(fd >= 0, "accept failed");
    return fd;
}
inline int connectPeer(int port) {
    Fd fd(::socket(AF_INET, SOCK_STREAM, 0));
    setup(fd.value >= 0, "creating peer socket failed");
    timeoutSocket(fd.value);
    sockaddr_in address;
    std::memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    address.sin_port = htons(static_cast<uint16_t>(port));
    setup(::connect(fd.value, reinterpret_cast<sockaddr*>(&address), sizeof(address)) == 0, "connecting to product server failed");
    int result = fd.value;
    fd.value = -1;
    return result;
}
struct Frame {
    unsigned opcode = 0;
    bool fin = false, compressed = false, masked = false;
    std::string payload;
};
inline std::string frame(unsigned opcode, bool fin, bool compressed, const std::string& payload, bool masked) {
    std::string result;
    result.push_back(static_cast<char>(opcode | (fin ? 128 : 0) | (compressed ? 64 : 0)));
    size_t n = payload.size();
    unsigned mask = masked ? 128 : 0;
    if (n < 126) result.push_back(static_cast<char>(mask | n));
    else if (n <= 65535) {
        result.push_back(static_cast<char>(mask | 126));
        result.push_back(static_cast<char>((n >> 8) & 255));
        result.push_back(static_cast<char>(n & 255));
    } else {
        result.push_back(static_cast<char>(mask | 127));
        for (int shift = 56; shift >= 0; shift -= 8) result.push_back(static_cast<char>((static_cast<uint64_t>(n) >> shift) & 255));
    }
    const unsigned char key[] = {0x12, 0x34, 0x56, 0x78};
    if (masked) result.append(reinterpret_cast<const char*>(key), 4);
    for (size_t i = 0; i < n; ++i) result.push_back(static_cast<char>(static_cast<unsigned char>(payload[i]) ^ (masked ? key[i % 4] : 0)));
    return result;
}
inline std::string closePayload(uint16_t code, const std::string& reason) {
    std::string result;
    result.push_back(static_cast<char>(code >> 8));
    result.push_back(static_cast<char>(code & 255));
    return result + reason;
}
struct Channel {
    Fd fd;
    SSL_CTX* context = nullptr;
    SSL* ssl = nullptr;
    explicit Channel(int descriptor) : fd(descriptor) { timeoutSocket(fd.value); }
    ~Channel() {
        if (ssl) SSL_free(ssl);
        if (context) SSL_CTX_free(context);
    }
    void encrypt(bool server) {
        context = SSL_CTX_new(TLS_method());
        setup(context != nullptr, "SSL_CTX_new failed");
        SSL_CTX_set_verify(context, SSL_VERIFY_NONE, nullptr);
        if (server) {
            setup(SSL_CTX_use_certificate_file(context, "test/.certs/trusted-server-crt.pem", SSL_FILETYPE_PEM) == 1, "loading TLS fixture certificate failed");
            setup(SSL_CTX_use_PrivateKey_file(context, "test/.certs/trusted-server-key.pem", SSL_FILETYPE_PEM) == 1, "loading TLS fixture key failed");
            setup(SSL_CTX_check_private_key(context) == 1, "TLS fixture key does not match certificate");
        }
        ssl = SSL_new(context);
        setup(ssl != nullptr && SSL_set_fd(ssl, fd.value) == 1, "SSL setup failed");
        setup((server ? SSL_accept(ssl) : SSL_connect(ssl)) == 1, "local TLS handshake failed");
    }
    void write(const std::string& bytes) {
        size_t sent = 0;
        while (sent < bytes.size()) {
            int amount = static_cast<int>(std::min<size_t>(16384, bytes.size() - sent));
            int n = ssl ? SSL_write(ssl, bytes.data() + sent, amount)
                        : static_cast<int>(::send(fd.value, bytes.data() + sent, amount, MSG_NOSIGNAL));
            setup(n > 0, "peer write failed before all requested bytes were sent");
            sent += static_cast<size_t>(n);
        }
    }
    int read(char* bytes, size_t length, int milliseconds) {
        if (!ssl || SSL_pending(ssl) == 0) {
            pollfd p;
            p.fd = fd.value;
            p.events = POLLIN;
            p.revents = 0;
            int ready = ::poll(&p, 1, std::max(1, milliseconds));
            if (ready == 0) return 0;
            setup(ready > 0, "peer poll failed");
        }
        int n = ssl ? SSL_read(ssl, bytes, static_cast<int>(length))
                    : static_cast<int>(::recv(fd.value, bytes, length, 0));
        return n > 0 ? n : -1;
    }
    bool exact(char* bytes, size_t length, int milliseconds = 2000) {
        size_t received = 0;
        auto until = Clock::now() + std::chrono::milliseconds(milliseconds);
        while (received < length) {
            int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(until - Clock::now()).count());
            if (remaining <= 0) return false;
            int n = read(bytes + received, length - received, remaining);
            if (n <= 0) return false;
            received += static_cast<size_t>(n);
        }
        return true;
    }
    std::string headers() {
        std::string result;
        auto until = Clock::now() + std::chrono::seconds(3);
        while (result.find("\r\n\r\n") == std::string::npos) {
            char c;
            int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(until - Clock::now()).count());
            setup(remaining > 0 && read(&c, 1, remaining) == 1, "HTTP upgrade headers incomplete or timed out");
            result.push_back(c);
            setup(result.size() < 65536, "HTTP upgrade headers exceed fixture limit");
        }
        return result;
    }
    int next(Frame& result, int milliseconds) {
        char first;
        int n = read(&first, 1, milliseconds);
        if (n <= 0) return n;
        unsigned char h[2];
        h[0] = static_cast<unsigned char>(first);
        setup(exact(reinterpret_cast<char*>(&h[1]), 1), "incomplete outbound frame header");
        result.opcode = h[0] & 15;
        result.fin = (h[0] & 128) != 0;
        result.compressed = (h[0] & 64) != 0;
        result.masked = (h[1] & 128) != 0;
        uint64_t length = h[1] & 127;
        if (length == 126 || length == 127) {
            int width = length == 126 ? 2 : 8;
            unsigned char extended[8] = {};
            setup(exact(reinterpret_cast<char*>(extended), width), "incomplete outbound extended frame length");
            length = 0;
            for (int i = 0; i < width; ++i) length = (length << 8) | extended[i];
        }
        setup(length <= 1024 * 1024, "outbound frame exceeds fixture limit");
        unsigned char mask[4] = {};
        if (result.masked) setup(exact(reinterpret_cast<char*>(mask), 4), "incomplete outbound mask");
        result.payload.assign(static_cast<size_t>(length), '\0');
        if (length) setup(exact(&result.payload[0], static_cast<size_t>(length)), "incomplete outbound payload");
        if (result.masked) for (size_t i = 0; i < result.payload.size(); ++i) result.payload[i] = static_cast<char>(static_cast<unsigned char>(result.payload[i]) ^ mask[i % 4]);
        return 1;
    }
};
inline std::string header(const std::string& input, const std::string& key) {
    std::string haystack = lower(input);
    size_t pos = haystack.find("\r\n" + lower(key) + ":");
    if (pos == std::string::npos) return "";
    pos += key.size() + 3;
    while (pos < input.size() && input[pos] == ' ') ++pos;
    size_t end = input.find("\r\n", pos);
    return input.substr(pos, end - pos);
}
inline std::string upgradeServer(Channel& channel, bool compression) {
    std::string request = channel.headers();
    std::string key = header(request, "Sec-WebSocket-Key");
    setup(!key.empty(), "client upgrade request has no WebSocket key");
    if (compression) setup(header(request, "Sec-WebSocket-Extensions").find("permessage-deflate") != std::string::npos, "client did not offer permessage-deflate");
    char accept[29] = {};
    WebSocketHandshakeKeyGen::generate(key, accept);
    std::string response = "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: " + std::string(accept, 28) + "\r\n";
    if (compression) response += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
    channel.write(response + "\r\n");
    return request;
}
inline std::string upgradeClient(Channel& channel, int port, bool compression) {
    std::string request = "GET / HTTP/1.1\r\nHost: localhost:" + std::to_string(port)
        + "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n";
    if (compression) request += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
    channel.write(request + "\r\n");
    std::string response = channel.headers();
    setup(response.find("HTTP/1.1 101 ") == 0, "server rejected HTTP upgrade: " + response);
    setup(header(response, "Sec-WebSocket-Accept") == "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", "server upgrade accept key differs from RFC fixture");
    if (compression) setup(header(response, "Sec-WebSocket-Extensions").find("permessage-deflate") != std::string::npos, "server did not negotiate permessage-deflate");
    return response;
}
struct Deflater {
    z_stream stream;
    Deflater() {
        std::memset(&stream, 0, sizeof(stream));
        setup(deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY) == Z_OK, "fixture deflate initialization failed");
    }
    ~Deflater() { deflateEnd(&stream); }
    std::string encode(const std::string& body) {
        stream.next_in = reinterpret_cast<Bytef*>(const_cast<char*>(body.data()));
        stream.avail_in = static_cast<uInt>(body.size());
        std::string result;
        do {
            char buffer[8192];
            stream.next_out = reinterpret_cast<Bytef*>(buffer);
            stream.avail_out = sizeof(buffer);
            setup(deflate(&stream, Z_SYNC_FLUSH) == Z_OK, "fixture deflate failed");
            result.append(buffer, sizeof(buffer) - stream.avail_out);
        } while (stream.avail_in || stream.avail_out == 0);
        const std::string tail("\x00\x00\xff\xff", 4);
        setup(result.size() >= 4 && result.compare(result.size() - 4, 4, tail) == 0, "fixture compression has no sync-flush tail");
        result.resize(result.size() - 4);
        return result;
    }
};
inline std::string body(size_t length, bool binary) {
    std::string result;
    uint32_t state = 0x6a09e667;
    for (size_t i = 0; i < length; ++i) {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        result.push_back(binary ? static_cast<char>(state & 255) : static_cast<char>('!' + state % 90));
    }
    return result;
}
inline std::string invalidPayload(bool partial) {
    if (!partial) return std::string(1, '\x07');
    const size_t length = 40960;
    std::string result(1, '\0');
    uint16_t n = static_cast<uint16_t>(length);
    uint16_t inverse = static_cast<uint16_t>(~n);
    result.push_back(static_cast<char>(n & 255));
    result.push_back(static_cast<char>(n >> 8));
    result.push_back(static_cast<char>(inverse & 255));
    result.push_back(static_cast<char>(inverse >> 8));
    result.append(length, 'A');
    result.push_back('\x07');
    return result;
}
inline void validateInvalidFixture(const std::string& payload, bool partial) {
    z_stream stream;
    std::memset(&stream, 0, sizeof(stream));
    setup(inflateInit2(&stream, -15) == Z_OK, "fixture inflate initialization failed");
    std::string input = payload + std::string("\x00\x00\xff\xff", 4);
    stream.next_in = reinterpret_cast<Bytef*>(&input[0]);
    stream.avail_in = static_cast<uInt>(input.size());
    int status = Z_OK;
    size_t produced = 0;
    do {
        unsigned char buffer[8192];
        stream.next_out = buffer;
        stream.avail_out = sizeof(buffer);
        status = inflate(&stream, Z_SYNC_FLUSH);
        produced += sizeof(buffer) - stream.avail_out;
    } while (status == Z_OK && (stream.avail_in || stream.avail_out == 0));
    inflateEnd(&stream);
    setup(status == Z_DATA_ERROR, "invalid fixture was not rejected by real zlib");
    setup(!partial || produced >= 40960, "partial-output fixture did not produce 40KiB before rejection");
}
struct Input { std::string body; size_t wire; bool binary; };
struct Checkpoint { bool reached; std::vector<Event> events; };
struct Exchange {
    std::vector<Event> events;
    std::vector<Input> expected;
    std::vector<Checkpoint> pending;
    std::vector<Frame> outbound;
    std::vector<std::string> expectedPings;
    std::vector<std::string> expectedPongs;
    size_t badWire = 0;
    bool closedNaturally = false, eof = false, closeSent = false;
    std::string closeWirePayload;
    Clock::time_point echoedAt;
    bool echoed = false;
};
struct Plan {
    bool server, binary;
    std::string mode;
    bool bad() const { return mode.compare(0, 3, "bad") == 0; }
    bool tls() const { return mode == "good_tls" || mode == "bad_tls"; }
    bool fragmented() const { return mode == "good_fragmented" || mode == "bad_fragmented"; }
    bool compression() const { return mode != "plain_disabled"; }
};
struct Finally {
    std::function<void()> function;
    explicit Finally(std::function<void()> f) : function(f) {}
    ~Finally() { if (function) function(); }
};
inline void checkpoint(Events& events, Exchange& result, size_t messages, size_t fragments, size_t pings, size_t pongs) {
    bool reached = events.wait([=](const std::vector<Event>& current) {
        return count(current, Type::Fragment) >= fragments && count(current, Type::Message) >= messages
            && count(current, Type::Ping) >= pings && count(current, Type::Pong) >= pongs;
    });
    result.pending.push_back(Checkpoint{reached, events.snapshot()});
}
inline void splitWrite(Channel& channel, const std::string& bytes, Events& events, Exchange& result) {
    setup(bytes.size() >= 3, "split-read fixture is too short");
    channel.write(bytes.substr(0, 1));
    std::this_thread::sleep_for(std::chrono::milliseconds(15));
    result.pending.push_back(Checkpoint{true, events.snapshot()});
    size_t headerLength = 2;
    unsigned char second = static_cast<unsigned char>(bytes[1]);
    if ((second & 127) == 126) headerLength += 2;
    if ((second & 127) == 127) headerLength += 8;
    if (second & 128) headerLength += 4;
    channel.write(bytes.substr(1, headerLength - 1));
    std::this_thread::sleep_for(std::chrono::milliseconds(15));
    result.pending.push_back(Checkpoint{true, events.snapshot()});
    size_t position = headerLength;
    if (bytes.size() - position > 1) {
        size_t amount = (bytes.size() - position) / 2;
        channel.write(bytes.substr(position, amount));
        position += amount;
        std::this_thread::sleep_for(std::chrono::milliseconds(15));
        result.pending.push_back(Checkpoint{true, events.snapshot()});
    }
    channel.write(bytes.substr(position));
}
inline Exchange receive(const Plan& plan, ix::WebSocket* reused = nullptr, bool verbose = false) {
    Events events(verbose);
    ix::WebSocket local;
    ix::WebSocket& websocket = reused ? *reused : local;
    std::unique_ptr<ix::WebSocketServer> server;
    std::unique_ptr<Fd> listening;
    int port = 0;
    Finally cleanup([&] {
        if (server) server->stop();
        else {
            websocket.stop();
            websocket.setOnMessageCallback([](const ix::WebSocketMessagePtr&) {});
        }
    });
    if (plan.server) {
        port = ix::getFreePort();
        setup(port > 0, "could not allocate local product-server port");
        server.reset(new ix::WebSocketServer(port, "127.0.0.1", 4, 4, 2, AF_INET, -1));
        if (!plan.compression()) server->disablePerMessageDeflate();
        if (plan.tls()) {
            ix::SocketTLSOptions options;
            options.tls = true;
            options.certFile = "test/.certs/trusted-server-crt.pem";
            options.keyFile = "test/.certs/trusted-server-key.pem";
            options.caFile = "NONE";
            server->setTLSOptions(options);
        }
        server->setOnClientMessageCallback([&](std::shared_ptr<ix::ConnectionState>, ix::WebSocket& socket, const ix::WebSocketMessagePtr& message) {
            if (message->type == Type::Open) socket.disableAutomaticReconnection();
            events.record(socket, message);
        });
        auto status = server->listen();
        setup(status.first, "product server listen failed: " + status.second);
        server->start();
    } else {
        listening.reset(new Fd(listener(port)));
        websocket.disableAutomaticReconnection();
        websocket.setHandshakeTimeout(2);
        websocket.setPingInterval(-1);
        websocket.setPerMessageDeflateOptions(ix::WebSocketPerMessageDeflateOptions(plan.compression(), false, false, 15, 15, false));
        ix::SocketTLSOptions options;
        options.caFile = "NONE";
        options.disable_hostname_validation = true;
        websocket.setTLSOptions(options);
        websocket.setUrl(std::string(plan.tls() ? "wss" : "ws") + "://localhost:" + std::to_string(port) + "/");
        websocket.setOnMessageCallback([&](const ix::WebSocketMessagePtr& message) { events.record(websocket, message); });
        websocket.start();
    }
    std::unique_ptr<Channel> channel(new Channel(plan.server ? connectPeer(port) : acceptPeer(listening->value)));
    if (plan.tls()) channel->encrypt(!plan.server);
    std::string handshake = plan.server ? upgradeClient(*channel, port, plan.compression()) : upgradeServer(*channel, plan.compression());
    if (plan.compression()) {
        std::string extension = header(handshake, "Sec-WebSocket-Extensions");
        setup(extension.find("client_no_context_takeover") == std::string::npos
            && extension.find("server_no_context_takeover") == std::string::npos, "context-takeover fixture negotiated a reset context");
    }
    setup(events.wait([](const std::vector<Event>& current) { return count(current, Type::Open) == 1; }), "Open callback did not arrive after completed upgrade");
    Exchange result;
    Deflater compressor;
    unsigned opcode = plan.binary ? 2 : 1;
    auto packet = [&](unsigned op, bool final, bool compressed, const std::string& payload) {
        return frame(op, final, compressed, payload, plan.server);
    };
    auto compressedMessage = [&](const std::string& value, bool expected) {
        std::string payload = compressor.encode(value);
        if (expected) result.expected.push_back(Input{value, payload.size(), plan.binary});
        return packet(opcode, true, true, payload);
    };
    auto controls = [&](const std::string& value) {
        result.expectedPings.push_back(value);
        result.expectedPongs.push_back(value);
        return packet(9, true, false, value) + packet(10, true, false, value);
    };
    auto following = [&]() {
        std::string a = compressor.encode("next");
        std::string b = compressor.encode("continued");
        size_t split = std::max<size_t>(1, b.size() / 2);
        return packet(opcode, true, true, a)
            + packet(opcode, false, true, b.substr(0, split))
            + packet(9, true, false, "later") + packet(10, true, false, "later")
            + packet(0, true, false, b.substr(split));
    };
    std::string late;
    if (plan.bad()) {
        bool partial = plan.mode == "bad_partial" || plan.mode == "bad_fragmented" || plan.mode == "bad_tls";
        std::string bad = invalidPayload(partial);
        validateInvalidFixture(bad, partial);
        result.badWire = bad.size();
        std::string prefix = compressedMessage("ready", true) + controls("heartbeat");
        late = following();
        std::ostringstream input;
        input << "receive compressed " << (plan.binary ? "BINARY" : "TEXT") << " payloadBytes=" << bad.size();
        if (bad.size() == 1) input << " payload=07";
        input << " followingFrameBytes=" << late.size();
        trace(verbose, input.str());
        if (plan.fragmented()) {
            size_t one = bad.size() / 3;
            size_t two = (bad.size() * 2) / 3;
            channel->write(prefix + packet(opcode, false, true, bad.substr(0, one)));
            checkpoint(events, result, 1, 1, 1, 1);
            channel->write(controls("fragment") + packet(0, false, false, bad.substr(one, two - one)));
            checkpoint(events, result, 1, 2, 2, 2);
            channel->write(packet(0, true, false, bad.substr(two)) + late);
        } else if (plan.mode == "bad_split") {
            channel->write(prefix);
            checkpoint(events, result, 1, 0, 1, 1);
            splitWrite(*channel, packet(opcode, true, true, bad), events, result);
            channel->write(late);
        } else channel->write(prefix + packet(opcode, true, true, bad) + late);
    } else {
        std::string value;
        if (plan.mode == "good_empty") value = "";
        else if (plan.mode == "good_context") value = body(6000, plan.binary);
        else if (plan.mode == "plain_negotiated" || plan.mode == "plain_disabled") value = plan.binary ? std::string("plain\0binary\xff", 13) : "plain text";
        else value = body(plan.mode == "good_split" ? 6000 : 45056, plan.binary);
        if (plan.mode == "plain_negotiated" || plan.mode == "plain_disabled") {
            result.expected.push_back(Input{value, value.size(), plan.binary});
            channel->write(packet(opcode, true, false, value));
        } else if (plan.mode == "good_context") {
            std::string bytes;
            for (int i = 0; i < 3; ++i) bytes += compressedMessage(value, true);
            channel->write(bytes);
        } else {
            std::string payload = compressor.encode(value);
            result.expected.push_back(Input{value, payload.size(), plan.binary});
            if (plan.fragmented()) {
                size_t one = payload.size() / 3;
                size_t two = (payload.size() * 2) / 3;
                channel->write(packet(opcode, false, true, payload.substr(0, one)));
                checkpoint(events, result, 0, 1, 0, 0);
                channel->write(controls("fragment") + packet(0, false, false, payload.substr(one, two - one)));
                checkpoint(events, result, 0, 2, 1, 1);
                channel->write(packet(0, true, false, payload.substr(two)));
            } else if (plan.mode == "good_split") splitWrite(*channel, packet(opcode, true, true, payload), events, result);
            else channel->write(packet(opcode, true, true, payload));
        }
        events.wait([&](const std::vector<Event>& current) { return count(current, Type::Message) >= result.expected.size() || count(current, Type::Error) > 0; });
        channel->write(packet(8, true, false, closePayload(1000, "finished")));
    }
    auto deadline = Clock::now() + std::chrono::seconds(2);
    bool sentAfterClose = false;
    while (Clock::now() < deadline) {
        Frame received;
        int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(deadline - Clock::now()).count());
        int status = channel->next(received, remaining);
        if (status < 0) { result.eof = true; break; }
        if (status == 0) break;
        result.outbound.push_back(received);
        if (received.opcode == 8) {
            if (!result.closeSent) result.closeWirePayload = received.payload;
            result.closeSent = true;
            std::ostringstream line;
            line << "outbound Close";
            if (received.payload.size() >= 2) {
                unsigned code = (static_cast<unsigned char>(received.payload[0]) << 8) | static_cast<unsigned char>(received.payload[1]);
                line << " code=" << code << " reason=" << quoted(received.payload.substr(2));
            } else line << " payload=" << quoted(received.payload);
            trace(verbose, line.str());
            if (plan.bad() && !sentAfterClose) {
                channel->write(late);
                sentAfterClose = true;
                if (plan.mode != "bad_timeout") {
                    channel->write(packet(8, true, false, received.payload));
                    result.echoedAt = Clock::now();
                    result.echoed = true;
                }
            }
        } else {
            trace(verbose, "outbound opcode=" + std::to_string(received.opcode) + " payload=" + quoted(received.payload));
        }
    }
    result.closedNaturally = events.wait([](const std::vector<Event>& current) { return count(current, Type::Close) >= 1; }, 1000);
    channel.reset();
    cleanup.function();
    cleanup.function = nullptr;
    result.events = events.snapshot();
    return result;
}
} // namespace pmd

