#include "pmd_peer.hpp"
#include <csignal>
namespace {
void check(bool condition, const std::string& detail) {
    if (!condition) throw std::runtime_error(detail);
}
bool describesFailure(const std::string& text) {
    std::string value = pmd::lower(text);
    bool compression = value.find("compress") != std::string::npos || value.find("deflate") != std::string::npos || value.find("zlib") != std::string::npos;
    bool failure = value.find("fail") != std::string::npos || value.find("invalid") != std::string::npos || value.find("error") != std::string::npos || value.find("corrupt") != std::string::npos;
    return compression && failure;
}
void verify(const pmd::Plan& plan, const pmd::Exchange& result) {
    using pmd::Type;
    check(result.closedNaturally, "Close callback did not occur before consumer cleanup");
    check(result.eof, "peer did not observe the connection terminate");
    check(pmd::count(result.events, Type::Open) == 1, "expected exactly one Open");
    check(pmd::count(result.events, Type::Close) == 1, "expected exactly one Close");
    std::vector<pmd::Event> messages, errors, closes;
    std::vector<std::string> pings, pongs;
    bool failed = false;
    for (const auto& e : result.events) {
        if (e.type == Type::Error) { failed = true; errors.push_back(e); }
        else if (failed) check(e.type != Type::Message && e.type != Type::Fragment && e.type != Type::Ping && e.type != Type::Pong, "data or control event delivered after decompression Error");
        if (e.type == Type::Message) messages.push_back(e);
        if (e.type == Type::Close) closes.push_back(e);
        if (e.type == Type::Ping) pings.push_back(e.body);
        if (e.type == Type::Pong) pongs.push_back(e.body);
        if (e.type == Type::Fragment) check(e.body.empty(), "Fragment callback leaked an unfinished body");
    }
    check(messages.size() == result.expected.size(), "Message count differs from complete legal input count: actual=" + std::to_string(messages.size()) + " expected=" + std::to_string(result.expected.size()));
    for (size_t i = 0; i < messages.size(); ++i) {
        check(messages[i].body == result.expected[i].body, "received complete body differs from input at message " + std::to_string(i));
        check(messages[i].binary == result.expected[i].binary, "binary flag differs from input");
        check(messages[i].wire == result.expected[i].wire, "wireSize includes headers or differs from summed compressed payload length");
        check(!messages[i].decompression, "legal Message marked as decompression failure");
    }
    check(pings == result.expectedPings, "Ping events differ from controls sent before failure/completion");
    check(pongs == result.expectedPongs, "Pong events differ from controls sent before failure/completion");
    for (const auto& pending : result.pending) {
        check(pending.reached, "expected public notification for a nonfinal fragment/control was missing");
        size_t expectedMessages = plan.bad() ? 1 : 0;
        check(pmd::count(pending.events, Type::Message) == expectedMessages, "unfinished frame/message delivered prematurely");
        check(pmd::count(pending.events, Type::Error) == 0, "incomplete legal frame or fragment caused premature Error");
        for (const auto& e : pending.events) if (e.type == Type::Fragment) check(e.body.empty(), "pending Fragment carried partial body");
    }
    if (plan.fragmented()) check(pmd::count(result.events, Type::Fragment) >= 2, "nonfinal continuation notifications missing");
    std::vector<std::string> wirePongs;
    size_t closeFrames = 0;
    for (const auto& f : result.outbound) {
        if (f.opcode == 10) wirePongs.push_back(f.payload);
        if (f.opcode == 8) ++closeFrames;
        check(f.opcode != 1 && f.opcode != 2, "send attempted inside Error callback reached the wire");
    }
    check(wirePongs == result.expectedPings, "automatic Pong missing before failure, or new Ping answered after failure");
    check(closeFrames == 1 && result.closeSent && result.closeWirePayload.size() >= 2, "expected one complete outbound Close frame");
    uint16_t code = static_cast<uint16_t>((static_cast<unsigned char>(result.closeWirePayload[0]) << 8) | static_cast<unsigned char>(result.closeWirePayload[1]));
    std::string reason = result.closeWirePayload.substr(2);
    if (plan.bad()) {
        check(errors.size() == 1, "expected exactly one decompression Error");
        const auto& e = errors[0];
        check(e.decompression, "errorInfo.decompressionError is false");
        check(describesFailure(e.reason), "errorInfo.reason does not describe invalid compression/decompression failure: " + e.reason);
        check(e.body.empty(), "Error exposed partially decompressed body");
        check(e.wire == result.badWire, "Error wireSize differs from entire compressed message payload: actual=" + std::to_string(e.wire) + " expected=" + std::to_string(result.badWire));
        check(e.state == ix::ReadyState::Closing, "connection was not Closing inside Error callback");
        check(!e.sendSucceeded, "sending inside Error callback reported success");
        check(code == 1007, "outbound Close code was " + std::to_string(code) + ", expected 1007");
        check(describesFailure(reason), "outbound Close reason does not describe invalid compressed payload: " + reason);
        check(closes[0].code == code && closes[0].reason == reason, "final Close lost the failure code/reason");
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(closes[0].at - e.at).count();
        std::cout << "observed Error wireSize=" << e.wire << " state=" << ix::WebSocket::readyStateToString(e.state)
                  << " send.success=" << e.sendSucceeded << " Close.code=" << closes[0].code
                  << " closeDelayMs=" << elapsed << '\n';
        if (plan.mode == "bad_timeout") {
            check(!result.echoed, "timeout scenario accidentally sent a Close reply");
            check(elapsed >= 200 && elapsed < 2000, "no-reply closing wait did not retain the existing 300ms deadline within scheduling tolerance");
        } else {
            check(result.echoed, "same-code/same-reason Close response was not sent");
            auto replyDelay = std::chrono::duration_cast<std::chrono::milliseconds>(closes[0].at - result.echoedAt).count();
            check(replyDelay < 250, "identical Close response did not terminate before the existing closing wait deadline");
        }
    } else {
        check(errors.empty(), "legal input emitted Error");
        check(code == 1000 && reason == "finished", "legal connection did not retain its ordinary close code/reason");
        check(closes[0].code == 1000 && closes[0].reason == "finished", "ordinary Close callback differs from wire Close");
    }
}
struct Case { std::string name; pmd::Plan plan; bool reconnect; };
std::vector<Case> cases() {
    const std::vector<std::string> modes = {
        "bad07", "bad_split", "bad_partial", "bad_fragmented", "bad_timeout",
        "good_empty", "good_large", "good_split", "good_fragmented", "good_context",
        "plain_negotiated", "plain_disabled", "good_tls", "bad_tls"
    };
    std::vector<Case> result;
    for (bool server : {false, true}) for (bool binary : {false, true}) {
        for (const auto& mode : modes) {
            std::string label = std::string(server ? "server" : "client") + "-" + (binary ? "binary" : "text") + "-" + mode;
            result.push_back(Case{label, pmd::Plan{server, binary, mode}, false});
        }
    }
    for (bool binary : {false, true}) result.push_back(Case{std::string("client-") + (binary ? "binary" : "text") + "-reconnect", pmd::Plan{false, binary, "bad_fragmented"}, true});
    return result;
}
}
int main(int argc, char** argv) {
    std::signal(SIGPIPE, SIG_IGN);
    ix::initNetSystem();
    std::vector<Case> available = cases();
    if (available.size() != 58) { std::cerr << "authoring error: expected 58 declared cases\n"; return 2; }
    if (argc == 2 && std::string(argv[1]) == "--list") {
        for (const auto& c : available) std::cout << c.name << '\n';
        std::cout << "Selected cases: " << available.size() << '\n';
        return 0;
    }
    if (argc != 2) { std::cerr << "Usage: receive_checks --list|all|case-name\n"; return 2; }
    std::string filter = argv[1];
    size_t selected = 0, executed = 0, failed = 0;
    for (const auto& c : available) if (filter == "all" || filter == c.name) ++selected;
    std::cout << "Selected cases: " << selected << '\n';
    if (selected == 0) { std::cerr << "No matching native cases\n"; return 2; }
    for (const auto& c : available) {
        if (filter != "all" && filter != c.name) continue;
        ++executed;
        std::cout << "CASE " << c.name << std::endl;
        try {
            if (c.reconnect) {
                ix::WebSocket sameObject;
                verify(c.plan, pmd::receive(c.plan, &sameObject));
                pmd::Plan next{false, c.plan.binary, "good_fragmented"};
                verify(next, pmd::receive(next, &sameObject));
            } else verify(c.plan, pmd::receive(c.plan));
            std::cout << "PASS " << c.name << '\n';
        } catch (const pmd::SetupError& error) {
            ++failed;
            std::cerr << "SETUP/PEER FAILURE " << c.name << ": " << error.what() << '\n';
        } catch (const std::exception& error) {
            ++failed;
            std::cerr << "ASSERTION FAILURE " << c.name << ": " << error.what() << '\n';
        }
    }
    std::cout << "Executed cases: " << executed << "; failed: " << failed << '\n';
    return executed == selected && failed == 0 ? 0 : 1;
}

