#include "pmd_peer.hpp"
#include <csignal>
int main() {
    std::signal(SIGPIPE, SIG_IGN);
    ix::initNetSystem();
    int port = 0;
    pmd::Fd listening(pmd::listener(port));
    std::string peerError;
    std::thread peer([&] {
        try {
            pmd::Channel channel(pmd::acceptPeer(listening.value));
            pmd::upgradeServer(channel, true);
            pmd::Deflater compressor;
            std::string data = compressor.encode("legacy callback");
            channel.write(pmd::frame(1, true, true, data, false)
                + pmd::frame(8, true, false, pmd::closePayload(1000, "finished"), false));
            pmd::Frame reply;
            while (channel.next(reply, 2000) > 0) if (reply.opcode == 8) break;
        } catch (const std::exception& error) { peerError = error.what(); }
    });
    ix::WebSocketTransport transport;
    size_t delivered = 0;
    bool correct = true, closed = false;
    transport.configure(ix::WebSocketPerMessageDeflateOptions(true, false, false, 15, 15, false), ix::SocketTLSOptions(), true, -1);
    transport.setOnCloseCallback([&](uint16_t code, const std::string& reason, size_t, bool) {
        closed = true;
        correct = correct && code == 1000 && reason == "finished";
        std::cout << "Close code=" << code << " reason=" << pmd::quoted(reason) << '\n';
    });
    ix::WebSocketTransport::OnMessageCallback callback =
        [&](const std::string& data, size_t wireSize, bool decompressionError, ix::WebSocketTransport::MessageKind kind) {
            ++delivered;
            correct = correct && data == "legacy callback" && wireSize > 0 && !decompressionError
                && kind == ix::WebSocketTransport::MessageKind::MSG_TEXT;
            std::cout << "Message str=" << pmd::quoted(data) << " wireSize=" << wireSize
                      << " decompressionError=" << std::boolalpha << decompressionError << '\n';
        };
    int exitCode = 1;
    try {
        auto result = transport.connectToUrl("ws://localhost:" + std::to_string(port) + "/", ix::WebSocketHttpHeaders(), 2);
        pmd::setup(result.success, "legacy consumer upgrade failed: " + result.errorStr);
        while (transport.getReadyState() != ix::WebSocketTransport::ReadyState::CLOSED) {
            auto polled = transport.poll();
            transport.dispatch(polled, callback);
        }
        exitCode = correct && closed && delivered == 1 ? 0 : 1;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        exitCode = 2;
    }
    transport.closeSocket();
    peer.join();
    if (!peerError.empty()) { std::cerr << peerError << '\n'; exitCode = 2; }
    return exitCode;
}

