219	inline std::string frame(unsigned opcode, bool fin, bool compressed, const std::string& payload, bool masked) {
220	    std::string result;
221	    result.push_back(static_cast<char>(opcode | (fin ? 128 : 0) | (compressed ? 64 : 0)));
222	    size_t n = payload.size();
223	    unsigned mask = masked ? 128 : 0;
224	    if (n < 126) result.push_back(static_cast<char>(mask | n));
225	    else if (n <= 65535) {
226	        result.push_back(static_cast<char>(mask | 126));
227	        result.push_back(static_cast<char>((n >> 8) & 255));
228	        result.push_back(static_cast<char>(n & 255));
229	    } else {
230	        result.push_back(static_cast<char>(mask | 127));
231	        for (int shift = 56; shift >= 0; shift -= 8) result.push_back(static_cast<char>((static_cast<uint64_t>(n) >> shift) & 255));
232	    }
233	    const unsigned char key[] = {0x12, 0x34, 0x56, 0x78};
234	    if (masked) result.append(reinterpret_cast<const char*>(key), 4);
235	    for (size_t i = 0; i < n; ++i) result.push_back(static_cast<char>(static_cast<unsigned char>(payload[i]) ^ (masked ? key[i % 4] : 0)));
236	    return result;
237	}
238	inline std::string closePayload(uint16_t code, const std::string& reason) {
239	    std::string result;
240	    result.push_back(static_cast<char>(code >> 8));
241	    result.push_back(static_cast<char>(code & 255));
242	    return result + reason;
243	}
