259	            setup(SSL_CTX_use_PrivateKey_file(context, "test/.certs/trusted-server-key.pem", SSL_FILETYPE_PEM) == 1, "loading TLS fixture key failed");
260	            setup(SSL_CTX_check_private_key(context) == 1, "TLS fixture key does not match certificate");
261	        }
262	        ssl = SSL_new(context);
263	        setup(ssl != nullptr && SSL_set_fd(ssl, fd.value) == 1, "SSL setup failed");
264	        setup((server ? SSL_accept(ssl) : SSL_connect(ssl)) == 1, "local TLS handshake failed");
265	    }
266	    void write(const std::string& bytes) {
267	        size_t sent = 0;
268	        while (sent < bytes.size()) {
269	            int amount = static_cast<int>(std::min<size_t>(16384, bytes.size() - sent));
270	            int n = ssl ? SSL_write(ssl, bytes.data() + sent, amount)
271	                        : static_cast<int>(::send(fd.value, bytes.data() + sent, amount, MSG_NOSIGNAL));
272	            setup(n > 0, "peer write failed before all requested bytes were sent");
273	            sent += static_cast<size_t>(n);
274	        }
275	    }
276	    int read(char* bytes, size_t length, int milliseconds) {
277	        if (!ssl || SSL_pending(ssl) == 0) {
278	            pollfd p;
279	            p.fd = fd.value;
280	            p.events = POLLIN;
281	            p.revents = 0;
282	            int ready = ::poll(&p, 1, std::max(1, milliseconds));
283	            if (ready == 0) return 0;
284	            setup(ready > 0, "peer poll failed");
285	        }
286	        int n = ssl ? SSL_read(ssl, bytes, static_cast<int>(length))
287	                    : static_cast<int>(::recv(fd.value, bytes, length, 0));
288	        return n > 0 ? n : -1;
289	    }
290	    bool exact(char* bytes, size_t length, int milliseconds = 2000) {
291	        size_t received = 0;
292	        auto until = Clock::now() + std::chrono::milliseconds(milliseconds);
293	        while (received < length) {
294	            int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(until - Clock::now()).count());
295	            if (remaining <= 0) return false;
296	            int n = read(bytes + received, length - received, remaining);
297	            if (n <= 0) return false;
298	            received += static_cast<size_t>(n);
299	        }
300	        return true;
301	    }
302	    std::string headers() {
303	        std::string result;
304	        auto until = Clock::now() + std::chrono::seconds(3);
305	        while (result.find("\r\n\r\n") == std::string::npos) {
306	            char c;
307	            int remaining = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(until - Clock::now()).count());
308	            setup(remaining > 0 && read(&c, 1, remaining) == 1, "HTTP upgrade headers incomplete or timed out");
309	            result.push_back(c);
310	            setup(result.size() < 65536, "HTTP upgrade headers exceed fixture limit");
311	        }
312	        return result;
313	    }
314	    int next(Frame& result, int milliseconds) {
315	        char first;
316	        int n = read(&first, 1, milliseconds);
317	        if (n <= 0) return n;
318	        unsigned char h[2];
319	        h[0] = static_cast<unsigned char>(first);
320	        setup(exact(reinterpret_cast<char*>(&h[1]), 1), "incomplete outbound frame header");
321	        result.opcode = h[0] & 15;
322	        result.fin = (h[0] & 128) != 0;
323	        result.compressed = (h[0] & 64) != 0;
324	        result.masked = (h[1] & 128) != 0;
325	        uint64_t length = h[1] & 127;
326	        if (length == 126 || length == 127) {
327	            int width = length == 126 ? 2 : 8;
328	            unsigned char extended[8] = {};
329	            setup(exact(reinterpret_cast<char*>(extended), width), "incomplete outbound extended frame length");
330	            length = 0;
331	            for (int i = 0; i < width; ++i) length = (length << 8) | extended[i];
332	        }
333	        setup(length <= 1024 * 1024, "outbound frame exceeds fixture limit");
334	        unsigned char mask[4] = {};
335	        if (result.masked) setup(exact(reinterpret_cast<char*>(mask), 4), "incomplete outbound mask");
336	        result.payload.assign(static_cast<size_t>(length), '\0');
337	        if (length) setup(exact(&result.payload[0], static_cast<size_t>(length)), "incomplete outbound payload");
338	        if (result.masked) for (size_t i = 0; i < result.payload.size(); ++i) result.payload[i] = static_cast<char>(static_cast<unsigned char>(result.payload[i]) ^ mask[i % 4]);
339	        return 1;
340	    }
341	};
342	inline std::string header(const std::string& input, const std::string& key) {
343	    std::string haystack = lower(input);
344	    size_t pos = haystack.find("\r\n" + lower(key) + ":");
345	    if (pos == std::string::npos) return "";
346	    pos += key.size() + 3;
347	    while (pos < input.size() && input[pos] == ' ') ++pos;
348	    size_t end = input.find("\r\n", pos);
349	    return input.substr(pos, end - pos);
350	}
351	inline std::string upgradeServer(Channel& channel, bool compression) {
352	    std::string request = channel.headers();
353	    std::string key = header(request, "Sec-WebSocket-Key");
354	    setup(!key.empty(), "client upgrade request has no WebSocket key");
355	    if (compression) setup(header(request, "Sec-WebSocket-Extensions").find("permessage-deflate") != std::string::npos, "client did not offer permessage-deflate");
356	    char accept[29] = {};
357	    WebSocketHandshakeKeyGen::generate(key, accept);
358	    std::string response = "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: " + std::string(accept, 28) + "\r\n";
359	    if (compression) response += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
360	    channel.write(response + "\r\n");
361	    return request;
362	}
363	inline std::string upgradeClient(Channel& channel, int port, bool compression) {
364	    std::string request = "GET / HTTP/1.1\r\nHost: localhost:" + std::to_string(port)
365	        + "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n";
366	    if (compression) request += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
367	    channel.write(request + "\r\n");
368	    std::string response = channel.headers();
369	    setup(response.find("HTTP/1.1 101 ") == 0, "server rejected HTTP upgrade: " + response);
