374	struct Deflater {
375	    z_stream stream;
376	    Deflater() {
377	        std::memset(&stream, 0, sizeof(stream));
378	        setup(deflateInit2(&stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY) == Z_OK, "fixture deflate initialization failed");
379	    }
380	    ~Deflater() { deflateEnd(&stream); }
381	    std::string encode(const std::string& body) {
382	        stream.next_in = reinterpret_cast<Bytef*>(const_cast<char*>(body.data()));
383	        stream.avail_in = static_cast<uInt>(body.size());
384	        std::string result;
385	        do {
386	            char buffer[8192];
387	            stream.next_out = reinterpret_cast<Bytef*>(buffer);
388	            stream.avail_out = sizeof(buffer);
389	            setup(deflate(&stream, Z_SYNC_FLUSH) == Z_OK, "fixture deflate failed");
390	            result.append(buffer, sizeof(buffer) - stream.avail_out);
391	        } while (stream.avail_in || stream.avail_out == 0);
392	        const std::string tail("\x00\x00\xff\xff", 4);
393	        setup(result.size() >= 4 && result.compare(result.size() - 4, 4, tail) == 0, "fixture compression has no sync-flush tail");
394	        result.resize(result.size() - 4);
395	        return result;
396	    }
397	};
398	inline std::string body(size_t length, bool binary) {
399	    std::string result;
400	    uint32_t state = 0x6a09e667;
401	    for (size_t i = 0; i < length; ++i) {
402	        state ^= state << 13;
403	        state ^= state >> 17;
404	        state ^= state << 5;
405	        result.push_back(binary ? static_cast<char>(state & 255) : static_cast<char>('!' + state % 90));
406	    }
407	    return result;
408	}
409	inline std::string invalidPayload(bool partial) {
410	    if (!partial) return std::string(1, '\x07');
411	    const size_t length = 40960;
412	    std::string result(1, '\0');
413	    uint16_t n = static_cast<uint16_t>(length);
414	    uint16_t inverse = static_cast<uint16_t>(~n);
415	    result.push_back(static_cast<char>(n & 255));
416	    result.push_back(static_cast<char>(n >> 8));
417	    result.push_back(static_cast<char>(inverse & 255));
418	    result.push_back(static_cast<char>(inverse >> 8));
419	    result.append(length, 'A');
420	    result.push_back('\x07');
421	    return result;
