471	inline void checkpoint(Events& events, Exchange& result, size_t messages, size_t fragments, size_t pings, size_t pongs) {
472	    bool reached = events.wait([=](const std::vector<Event>& current) {
473	        return count(current, Type::Fragment) >= fragments && count(current, Type::Message) >= messages
474	            && count(current, Type::Ping) >= pings && count(current, Type::Pong) >= pongs;
475	    });
476	    result.pending.push_back(Checkpoint{reached, events.snapshot()});
477	}
478	inline void splitWrite(Channel& channel, const std::string& bytes, Events& events, Exchange& result) {
479	    setup(bytes.size() > 3, "split-read fixture is too short");
480	    channel.write(bytes.substr(0, 1));
481	    std::this_thread::sleep_for(std::chrono::milliseconds(15));
482	    result.pending.push_back(Checkpoint{true, events.snapshot()});
483	    size_t headerLength = 2;
484	    unsigned char second = static_cast<unsigned char>(bytes[1]);
485	    if ((second & 127) == 126) headerLength += 2;
486	    if ((second & 127) == 127) headerLength += 8;
487	    if (second & 128) headerLength += 4;
488	    channel.write(bytes.substr(1, headerLength - 1));
489	    std::this_thread::sleep_for(std::chrono::milliseconds(15));
490	    result.pending.push_back(Checkpoint{true, events.snapshot()});
491	    size_t position = headerLength;
492	    if (bytes.size() - position > 1) {
493	        size_t amount = (bytes.size() - position) / 2;
494	        channel.write(bytes.substr(position, amount));
495	        position += amount;
496	        std::this_thread::sleep_for(std::chrono::milliseconds(15));
497	        result.pending.push_back(Checkpoint{true, events.snapshot()});
498	    }
499	    channel.write(bytes.substr(position));
500	}
