#include "pmd_peer.hpp"
#include <csignal>
namespace {
void check(bool condition, const std::string& detail) {
    if (!condition) throw std::runtime_error(detail);
}
bool describesFailure(const std::string& text) {
    std::string value = pmd::lower(text);
    bool compression = value.find("compress") != std::string::npos || value.find("deflate") != std::string::npos || value.find("zlib") != std::string::npos;
    bool failure = value.find("fail") != std::string::npos || value.find("invalid") != std::string::npos || value.find("error") != std::string::npos || value.find("corrupt") != std::string::npos;
    return compression && failure;
}
void verify(const pmd::Plan& plan, const pmd::Exchange& result) {
    using pmd::Type;
    check(result.closedNaturally, "Close callback did not occur before consumer cleanup");
    check(result.eof, "peer did not observe the connection terminate");
    check(pmd::count(result.events, Type::Open) == 1, "expected exactly one Open");
    check(pmd::count(result.events, Type::Close) == 1, "expected exactly one Close");
    std::vector<pmd::Event> messages, errors, closes;
    std::vector<std::string> pings, pongs;
    bool failed = false;
    for (const auto& e : result.events) {
        if (e.type == Type::Error) { failed = true; errors.push_back(e); }
        else if (failed) check(e.type != Type::Message && e.type != Type::Fragment && e.type != Type::Ping && e.type != Type::Pong, "data or control event delivered after decompression Error");
        if (e.type == Type::Message) messages.push_back(e);
        if (e.type == Type::Close) closes.push_back(e);
        if (e.type == Type::Ping) pings.push_back(e.body);
        if (e.type == Type::Pong) pongs.push_back(e.body);
        if (e.type == Type::Fragment) check(e.body.empty(), "Fragment callback leaked an unfinished body");
    }
    check(messages.size() == result.expected.size(), "Message count differs from complete legal input count: actual=" + std::to_string(messages.size()) + " expected=" + std::to_string(result.expected.size()));
    for (size_t i = 0; i < messages.size(); ++i) {
        check(messages[i].body == result.expected[i].body, "received complete body differs from input at message " + std::to_string(i));
        check(messages[i].binary == result.expected[i].binary, "binary flag differs from input");
        check(messages[i].wire == result.expected[i].wire, "wireSize includes headers or differs from summed compressed payload length");
        check(!messages[i].decompression, "legal Message marked as decompression failure");
    }
    check(pings == result.expectedPings, "Ping events differ from controls sent before failure/completion");
    check(pongs == result.expectedPongs, "Pong events differ from controls sent before failure/completion");
    for (const auto& pending : result.pending) {
        check(pending.reached, "expected public notification for a nonfinal fragment/control was missing");
        size_t expectedMessages = plan.bad() ? 1 : 0;
        check(pmd::count(pending.events, Type::Message) == expectedMessages, "unfinished frame/message delivered prematurely");
        check(pmd::count(pending.events, Type::Error) == 0, "incomplete legal frame or fragment caused premature Error");
        for (const auto& e : pending.events) if (e.type == Type::Fragment) check(e.body.empty(), "pending Fragment carried partial body");
