    check(wirePongs == result.expectedPings, "automatic Pong missing before failure, or new Ping answered after failure");
    check(closeFrames == 1 && result.closeSent && result.closeWirePayload.size() >= 2, "expected one complete outbound Close frame");
    uint16_t code = static_cast<uint16_t>((static_cast<unsigned char>(result.closeWirePayload[0]) << 8) | static_cast<unsigned char>(result.closeWirePayload[1]));
