struct Case { std::string name; pmd::Plan plan; bool reconnect; };
std::vector<Case> cases() {
    const std::vector<std::string> modes = {
        "bad07", "bad_split", "bad_partial", "bad_fragmented", "bad_timeout",
        "good_empty", "good_large", "good_split", "good_fragmented", "good_context",
        "plain_negotiated", "plain_disabled", "good_tls", "bad_tls"
    };
    std::vector<Case> result;
    for (bool server : {false, true}) for (bool binary : {false, true}) {
        for (const auto& mode : modes) {
            std::string label = std::string(server ? "server" : "client") + "-" + (binary ? "binary" : "text") + "-" + mode;
            result.push_back(Case{label, pmd::Plan{server, binary, mode}, false});
        }
    }
    for (bool binary : {false, true}) result.push_back(Case{std::string("client-") + (binary ? "binary" : "text") + "-reconnect", pmd::Plan{false, binary, "bad_fragmented"}, true});
    return result;
}
}
int main(int argc, char** argv) {
    std::signal(SIGPIPE, SIG_IGN);
    ix::initNetSystem();
    std::vector<Case> available = cases();
    if (available.size() != 58) { std::cerr << "authoring error: expected 58 declared cases\n"; return 2; }
    if (argc == 2 && std::string(argv[1]) == "--list") {
        for (const auto& c : available) std::cout << c.name << '\n';
        std::cout << "Selected cases: " << available.size() << '\n';
        return 0;
    }
    if (argc != 2) { std::cerr << "Usage: receive_checks --list|all|case-name\n"; return 2; }
    std::string filter = argv[1];
    size_t selected = 0, executed = 0, failed = 0;
    for (const auto& c : available) if (filter == "all" || filter == c.name) ++selected;
    std::cout << "Selected cases: " << selected << '\n';
    if (selected == 0) { std::cerr << "No matching native cases\n"; return 2; }
    for (const auto& c : available) {
        if (filter != "all" && filter != c.name) continue;
        ++executed;
        std::cout << "CASE " << c.name << std::endl;
        try {
            if (c.reconnect) {
                ix::WebSocket sameObject;
                verify(c.plan, pmd::receive(c.plan, &sameObject));
                pmd::Plan next{false, c.plan.binary, "good_fragmented"};
                verify(next, pmd::receive(next, &sameObject));
            } else verify(c.plan, pmd::receive(c.plan));
            std::cout << "PASS " << c.name << '\n';
        } catch (const pmd::SetupError& error) {
            ++failed;
            std::cerr << "SETUP/PEER FAILURE " << c.name << ": " << error.what() << '\n';
        } catch (const std::exception& error) {
            ++failed;
            std::cerr << "ASSERTION FAILURE " << c.name << ": " << error.what() << '\n';
        }
    }
    std::cout << "Executed cases: " << executed << "; failed: " << failed << '\n';
    return executed == selected && failed == 0 ? 0 : 1;
}
