    transport.setOnCloseCallback([&](uint16_t code, const std::string& reason, size_t, bool) {
        closed = true;
        correct = correct && code == 1000 && reason == "finished";
        std::cout << "Close code=" << code << " reason=" << pmd::quoted(reason) << '\n';
    });
    ix::WebSocketTransport::OnMessageCallback callback =
        [&](const std::string& data, size_t wireSize, bool decompressionError, ix::WebSocketTransport::MessageKind kind) {
            ++delivered;
            correct = correct && data == "legacy callback" && wireSize > 0 && !decompressionError
