                      << " decompressionError=" << std::boolalpha << decompressionError << '\n';
        };
    int exitCode = 1;
    try {
        auto result = transport.connectToUrl("ws://localhost:" + std::to_string(port) + "/", ix::WebSocketHttpHeaders(), 2);
        pmd::setup(result.success, "legacy consumer upgrade failed: " + result.errorStr);
        while (transport.getReadyState() != ix::WebSocketTransport::ReadyState::CLOSED) {
            auto polled = transport.poll();
            transport.dispatch(polled, callback);
        }
        exitCode = correct && closed && delivered == 1 ? 0 : 1;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        exitCode = 2;
    }
    transport.closeSocket();
    peer.join();
    if (!peerError.empty()) { std::cerr << peerError << '\n'; exitCode = 2; }
    return exitCode;
